-- ============================================================
-- REFYN — QUESTION BANK SEED (part 3 of 4)
-- Source: Refyn_Question_Intake_8_fixed.xlsx, sheet "Question_Intake"
-- Rows 401-600 of 613
--
-- Run AFTER master_setup.sql + seed_taxonomy.sql, in the Supabase SQL Editor.
-- Idempotent: re-running skips rows already present (exam_id, external_id).
--
-- Transforms applied to the sheet data:
--   * question_type / correct_answer (MCQ) lowercased to match existing seeds
--   * calculation_level 'hard'->'high', 'easy'->'low' (CHECK allows low/medium/high)
--   * TITA rows get NULL options
--   * 39 solutions that were left mid-draft in the sheet were re-derived and
--     rewritten; answer keys were verified unchanged.
--   * subtopic resolved by concept_code; a row whose code is missing from
--     subtopics would be skipped -- the verification query at the end of
--     part 4 reports the final count.
-- ============================================================

INSERT INTO questions (
  exam_id, subtopic_id,
  external_id, year, slot, source, is_pyq,
  question_text, question_type,
  option_a, option_b, option_c, option_d,
  correct_answer, solution, alternate_solution,
  difficulty, calculation_level, logic_level,
  expected_time_seconds, common_mistakes
)
SELECT
  (SELECT id FROM exams WHERE slug = 'cat'), s.id,
  v.external_id, v.year, v.slot, v.source, v.is_pyq,
  v.question_text, v.question_type,
  v.option_a, v.option_b, v.option_c, v.option_d,
  v.correct_answer, v.solution, v.alternate_solution,
  v.difficulty, v.calculation_level, v.logic_level,
  v.expected_time_seconds, v.common_mistakes
FROM (VALUES
  ('CAT2020_QA_S1_18', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'TSD_BASIC', 'Leaving home at the same time, Amal reaches the office at 10:15 am if he travels at 8 km/hr, and at 9:40 am if he travels at 15 km/hr. Leaving home at 9.10 am, at what speed, in km/hr, must he travel so as to reach office exactly at 10 am?', 'mcq', '13', '12', '14', '11', 'b', 'The time difference between the two given scenarios for the same distance d is 35 minutes: d/8 - d/15 = 35/60, giving d=10 km. To cover this 10 km in the 50 minutes between 9:10 am and 10:00 am, the required speed is 10/(50/60) = 12 km/hr.', NULL, 7, 'medium', 'medium', 150, 'Trying to find the required speed without first determining the actual distance between home and office.'),
  ('CAT2020_QA_S1_19', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'TSD_BASIC', 'A train travelled at one-thirds of its usual speed, and hence reached the destination 30 minutes after the scheduled time. On its return journey, the train initially travelled at its usual speed for 5 minutes but then stopped for 4 minutes for an emergency. The percentage by which the train must now increase its usual speed so as to reach the destination at the scheduled time, is nearest to', 'mcq', '50', '58', '67', '61', 'c', 'Travelling at one-third speed triples the time taken, and this extra time equals 30 minutes, so the usual travel time works out to 15 minutes. On the return trip, 5 minutes at usual speed plus a 4-minute stoppage leaves only 6 minutes (instead of the usual remaining 10 minutes) to cover the remaining distance, requiring a speed of (10/6) times usual, i.e. an increase of about 67%.', NULL, 9, 'high', 'high', 180, 'Forgetting to subtract the 4-minute stoppage from the time remaining before calculating the required speed increase.'),
  ('CAT2020_QA_S1_20', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'NS_MISC', 'The mean of all 4-digit even natural numbers of the form ''aabb'', where a > 0, is', 'mcq', '4466', '5050', '4864', '5544', 'd', 'Each such number equals 1100a + 11b, with a ranging uniformly over 1-9 (average 5) and b, needed for evenness, ranging over {0,2,4,6,8} (average 4). The mean of all such numbers is 1100(5) + 11(4) = 5500+44 = 5544.', NULL, 6, 'medium', 'medium', 150, 'Including a=0 in the range for a, or miscalculating the average of the restricted even-digit set for b.'),
  ('CAT2020_QA_S1_21', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'TSD_TRAIN', 'Two persons are walking beside a railway track at respective speeds of 2 and 4 km per hour in the same direction. A train came from behind them and crossed them in 90 and 100 seconds, respectively. The time, in seconds, taken by the train to cross an electric post is nearest to', 'mcq', '87', '82', '78', '75', 'b', 'Let the train''s speed be s kmph and length l km. Using relative speed for each crossing: l=(s-2)(90/3600) and l=(s-4)(100/3600). Equating and solving gives s=22 kmph, and l=0.5 km. Time to cross a stationary post = l/s = 0.5/22 hr ≈ 82 seconds.', NULL, 7, 'medium', 'high', 150, 'Using the train''s own speed directly instead of the relative speed (train minus walker) when computing the train''s length.'),
  ('CAT2020_QA_S1_22', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'NS_FACTORS', 'If a, b and c are positive integers such that ab = 432, bc = 96 and c < 9, then the smallest possible value of a + b + c is', 'mcq', '49', '56', '59', '46', 'd', 'Testing valid divisor pairs of bc=96 with c<9 (and checking ab=432 gives integer a for the corresponding b): c=4, b=24, a=18 gives a sum of 46, which is the smallest among all valid combinations checked.', NULL, 8, 'high', 'high', 150, 'Testing only one or two factor combinations of bc=96 instead of systematically checking all valid divisor pairs with c<9.'),
  ('CAT2020_QA_S1_23', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'PERC_BASIC', 'In a group of people, 28% of the members are young while the rest are old. If 65% of the members are literates, and 25% of the literates are young, then the percentage of old people among the illiterates is nearest to', 'mcq', '62', '55', '59', '66', 'd', 'Taking 100 people: illiterate=35, literate=65 with young literates=25%(65)=16.25 and old literates=48.75. Old people overall = 72 (100-28). Old illiterates = 72-48.75 = 23.25. As a percentage of illiterates (35), this is 23.25/35 x 100 ≈ 66%.', NULL, 7, 'medium', 'medium', 150, 'Expressing old illiterates as a percentage of the total group instead of as a percentage of illiterates specifically.'),
  ('CAT2020_QA_S1_24', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'SI_BASIC', 'Veeru invested Rs 10000 at 5% simple annual interest, and exactly after two years, Joy invested Rs 8000 at 10% simple annual interest. How many years after Veeru''s investment, will their balances, i.e., principal plus accumulated interest, be equal?', 'tita', NULL, NULL, NULL, NULL, '12', 'Measuring time t from Veeru''s start: Veeru''s balance = 10000(1+0.05t), and Joy''s balance (invested 2 years later) = 8000(1+0.10(t-2)). Equating and solving gives t=12.', NULL, 6, 'medium', 'medium', 150, 'Using t instead of (t-2) for the duration of Joy''s investment, since Joy starts two years after Veeru.'),
  ('CAT2020_QA_S1_25', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'ALG_FUNC_GRAPH', 'If for every real x, f(5 + x) = f(5 - x) and f(x) = 0 has four distinct real roots, then the sum of these roots is', 'mcq', '0', '40', '10', '20', 'd', 'The symmetry condition means the graph of f is symmetric about x=5, so every root r pairs with another root (10-r). With four distinct roots forming two such pairs, each pair sums to 10, giving a total root sum of 20.', NULL, 6, 'medium', 'medium', 120, 'Assuming the symmetry is about x=0 rather than correctly about x=5.'),
  ('CAT2020_QA_S1_26', 2020, 'Slot 1', 'CAT 2020 Slot 1 (Cracku PYQ compilation)', TRUE, 'ALG_LINEAR_WORD', 'Let A, B and C be three positive integers such that the sum of A and the mean of B and C is 5. In addition, the sum of B and the mean of A and C is 7. Then the sum of A and B is', 'mcq', '5', '4', '6', '7', 'c', 'The two conditions give 2A+B+C=10 and A+2B+C=14. Subtracting, B-A=4, so B=A+4. Testing positive integer values: A=1 gives B=5 and C=3 (all positive, valid); A=2 gives C=0, which is invalid since C must be positive. So A=1, B=5, C=3, and A+B=6.', NULL, 6, 'medium', 'medium', 120, 'Not enforcing that C must be a positive integer, which rules out larger values of A.'),
  ('CAT2018_QA_S1_01', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_LOG', 'If x is a positive quantity such that 2^x = 3^(log5 2), then x is equal to', 'mcq', 'log5 8', '1 + log3(5/3)', 'log5 9', '1 + log5(3/5)', 'd', '2^x = 2^(log5 3), so x = log5 3 = log5(5*3/5) = 1 + log5(3/5).', NULL, 6, 'medium', 'medium', 90, 'Mixing up which base the log should be converted to.'),
  ('CAT2018_QA_S1_02', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'GEO_CIRCLE_CHORD', 'In a circle, two parallel chords on the same side of a diameter have lengths 4 cm and 6 cm. If the distance between these chords is 1 cm, then the radius of the circle, in cm, is', 'mcq', '√13', '√14', '√11', '√12', 'a', 'Drop perpendiculars from centre to both chords; if OM = x, AO²=3²+x² and CO²=2²+(x+1)². Equate (both = radius²) to get x=2, so radius=√13.', NULL, 6, 'medium', 'medium', 120, 'Forgetting both chords are on the same side, leading to wrong sign on the distance term.'),
  ('CAT2018_QA_S1_03', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'TW_COMBINED', 'Humans and robots can both perform a job but at different efficiencies. Fifteen humans and five robots working together take thirty days to finish the job, whereas five humans and fifteen robots working together take sixty days to finish it. How many days will fifteen humans working together (without any robot) take to finish it?', 'mcq', '45', '36', '32', '40', 'c', 'Equate total work: (15h+5r)*30=(5h+15r)*60 gives h=5r. Total work=480h; 15 humans finish in 480h/15h=32 days.', NULL, 6, 'medium', 'medium', 120, 'Not converting both equations to the same "total work" unit before comparing.'),
  ('CAT2018_QA_S1_04', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'GEO_CYCLIC', 'Let ABCD be a rectangle inscribed in a circle of radius 13 cm. Which one of the following pairs can represent, in cm, the possible length and breadth of ABCD?', 'mcq', '24, 10', '25, 9', '25, 10', '24, 12', 'a', 'Diagonal = 2*13 = 26, so l²+b²=676. Only 24²+10²=676 satisfies this among the options.', NULL, 5, 'low', 'low', 90, 'Using radius instead of diameter as the diagonal.'),
  ('CAT2018_QA_S1_05', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'GEO_QUAD', 'Points E, F, G, H lie on the sides AB, BC, CD, and DA, respectively, of a square ABCD. If EFGH is also a square whose area is 62.5% of that of ABCD and CG is longer than EB, then the ratio of length of EB to that of CG is', 'mcq', '3 : 8', '2 : 5', '4 : 9', '1 : 3', 'd', 'Let side of ABCD = x+1 with EB=1, AE=x. Area(EFGH)=x²+1=5(x+1)²/8, giving x=3 or 1/3. Since CG>EB, ratio EB:CG=1:3.', NULL, 8, 'high', 'high', 150, 'Forgetting the "CG longer than EB" condition, which picks the correct root of the quadratic.'),
  ('CAT2018_QA_S1_06', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'TSD_RELATIVE', 'Point P lies between points A and B such that the length of BP is thrice that of AP. Car 1 starts from A and moves towards B. Simultaneously, car 2 starts from B and moves towards A. Car 2 reaches P one hour after car 1 reaches P. If the speed of car 2 is half that of car 1, then the time, in minutes, taken by car 1 in reaching P from A is', 'tita', NULL, NULL, NULL, NULL, '12', 'Let AP=x, BP=3x, car1 speed s, car2 speed 0.5s. x/s+60=3x/(0.5s)=6x/s → 5x/s=60 → x/s=12 minutes.', NULL, 6, 'medium', 'medium', 120, 'Mixing up which car is faster when setting up the time-difference equation.'),
  ('CAT2018_QA_S1_07', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_FUNC_OPT', 'Let f(x) = min(2x², 52 − 5x) where x is any positive real number. Then the maximum possible value of f(x) is', 'tita', NULL, NULL, NULL, NULL, '32', 'Maximum of the min-function occurs where the two pieces meet: 2x²=52−5x → 2x²+5x−52=0 → x=4 (rejecting negative root). f(4)=2*16=32.', NULL, 6, 'medium', 'medium', 120, 'Taking the negative root of x, which is invalid since x must be positive.'),
  ('CAT2018_QA_S1_08', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_SPECIAL', 'While multiplying three real numbers, Ashok took one of the numbers as 73 instead of 37. As a result, the product went up by 720. Then the minimum possible value of the sum of squares of the other two numbers is', 'tita', NULL, NULL, NULL, NULL, '40', '(73−37)*ab=720 → ab=20. Minimum of a²+b² for fixed product ab=20 occurs at a=b=√20, giving a²+b²=40.', NULL, 7, 'medium', 'medium', 120, 'Forgetting that minimum sum of squares for a fixed product happens when the two numbers are equal.'),
  ('CAT2018_QA_S1_09', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'TSD_TRAIN', 'Train T leaves station X for station Y at 3 pm. Train S, traveling at three quarters of the speed of T, leaves Y for X at 4 pm. The two trains pass each other at a station Z, where the distance between X and Z is three-fifths of that between X and Y. How many hours does train T take for its journey from X to Y?', 'tita', NULL, NULL, NULL, NULL, '15', 'Let meeting time be x hours after 3pm. Distance ratio (xt)/((x-1)*0.75t)=3/2 gives x=9 hours for 3/5 of the journey, so full journey = 9*(5/3)=15 hours.', NULL, 6, 'high', 'high', 150, 'Not accounting for the one-hour head start of train T when comparing travel times.'),
  ('CAT2018_QA_S1_10', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'MIX_ALLIGATION', 'Two types of tea, A and B, are mixed and then sold at Rs. 40 per kg. The profit is 10% if A and B are mixed in the ratio 3 : 2, and 5% if this ratio is 2 : 3. The cost prices, per kg, of A and B are in the ratio', 'mcq', '17 : 25', '18 : 25', '19 : 24', '21 : 25', 'c', 'Set up (3a+2b)/5=40/1.1 and (2a+3b)/5=40/1.05, solve simultaneously to get a/b=19/24.', NULL, 6, 'high', 'medium', 150, 'Applying the profit percentage to the wrong base (selling price vs cost price).'),
  ('CAT2018_QA_S1_11', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_GP', 'Given an equilateral triangle T1 with side 24 cm, a second triangle T2 is formed by joining the midpoints of the sides of T1. Then a third triangle T3 is formed similarly. If this continues, the sum of the areas of infinitely many such triangles T1, T2, T3,... will be', 'mcq', '188√3', '248√3', '164√3', '192√3', 'd', 'Each triangle has 1/4 the area of the previous, forming a GP. Area(T1)=144√3, sum = T1/(1−1/4) = (4/3)*144√3 = 192√3.', NULL, 6, 'medium', 'low', 120, 'Using ratio 1/2 instead of 1/4 for areas (confusing side ratio with area ratio).'),
  ('CAT2018_QA_S1_12', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_LOG', 'If log12(81) = p, then 3(4−p)/(4+p) is equal to', 'mcq', 'log4 16', 'log6 16', 'log2 8', 'log6 8', 'd', 'Using componendo-dividendo on 1+log3(4)=4/p leads to 3(4−p)/(4+p)=log6 8.', NULL, 7, 'high', 'high', 150, 'Errors while applying componendo-dividendo to the logarithmic expression.'),
  ('CAT2018_QA_S1_13', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'CI_ANNUAL', 'John borrowed Rs. 2,10,000 from a bank at an interest rate of 10% per annum, compounded annually. The loan was repaid in two equal instalments, the first after one year and the second after another year. Then each instalment, in Rs., is', 'tita', NULL, NULL, NULL, NULL, '121000', 'Bring both instalments to the end of year 2: 1.1x + x = 210000*1.1*1.1 = 254100, so 2.1x=254100, x=121000.', NULL, 6, 'medium', 'medium', 120, 'Discounting instalments to the wrong point in time.'),
  ('CAT2018_QA_S1_14', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'TW_COMBINED', 'When they work alone, B needs 25% more time to finish a job than A does. They finish the job in 13 days: A works alone till half the job is done, then A and B work together for four days, and finally B works alone to complete the remaining 5% of the job. In how many days can B alone finish the entire job?', 'mcq', '20', '22', '16', '18', 'a', 'With a=1.25b, 4 days together complete 45% of work: 4a+4b=45 → 9b=45 → b=5 units/day. Total work=100 units, so B alone takes 100/5=20 days.', NULL, 7, 'high', 'high', 150, 'Misreading which portion (50%, 45%, 5%) belongs to which phase of the work.'),
  ('CAT2018_QA_S1_15', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'MOD_SELECT', 'How many numbers with two or more digits can be formed with the digits 1,2,...,9, so that in every such number, each digit is used at most once and the digits appear in ascending order?', 'tita', NULL, NULL, NULL, NULL, '502', 'Sum of 9Cr for r=2 to 9 = 2^9 − 9C0 − 9C1 = 512 − 1 − 9 = 502.', NULL, 6, 'medium', 'medium', 120, 'Forgetting to subtract single-digit selections (r=0,1) from the total 2^9.'),
  ('CAT2018_QA_S1_16', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'GEO_CONE', 'A right circular cone, of height 12 ft, stands on its base which has diameter 8 ft. The tip is cut off with a plane parallel to the base, 9 ft from the base. With π=22/7, the volume, in cubic ft, of the remaining part is', 'tita', NULL, NULL, NULL, NULL, '198', 'Small cone (top 3 ft) has radius 1 ft by similar triangles. Remaining volume = (1/3)π(4²*12 − 1²*3) = (1/3)π*189 = 198.', NULL, 7, 'high', 'medium', 150, 'Using the full height instead of the cut-off top cone height when finding the small radius.'),
  ('CAT2018_QA_S1_17', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'RATIO_BASIC', 'Raju and Lalitha originally had marbles in the ratio 4:9. Then Lalitha gave some marbles to Raju, so the ratio became 5:6. What fraction of her original marbles did Lalitha give to Raju?', 'mcq', '1/5', '6/19', '1/4', '7/33', 'd', 'With 4x and 9x marbles and a given away, (4x+a)/(9x−a)=5/6 gives a/x=21/11, so a/9x=7/33.', NULL, 5, 'medium', 'medium', 90, 'Dividing by the wrong original quantity (Raju''s instead of Lalitha''s) when forming the fraction.'),
  ('CAT2018_QA_S1_18', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'SET_VENN', 'Each of 74 students in a class studies at least one of H, E and P. Ten students study all three, twenty study H and E but not P. Every student who studies P also studies H or E. If the number studying H equals that studying E, the number of students studying H is', 'tita', NULL, NULL, NULL, NULL, '52', 'Let x = students in H-only + H&P-only (equal to same for E by symmetry): x+20+10+x=74 → x=22. Students studying H = 22+10+20=52.', NULL, 6, 'high', 'high', 150, 'Not using the symmetry condition (H count = E count) to set up a single variable.'),
  ('CAT2018_QA_S1_19', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'PL_CP_SP', 'A wholesaler bought walnuts and peanuts, walnut price per kg thrice that of peanut. He sold 8 kg peanuts at 10% profit and 16 kg walnuts at 20% profit to a shopkeeper, who lost 5 kg walnuts and 3 kg peanuts in transit, then sold the remaining mix at Rs. 166/kg for an overall 25% profit. At what price, in Rs/kg, did the wholesaler buy walnuts?', 'mcq', '96', '98', '86', '84', 'a', 'Set peanut CP=100x, walnut CP=300x. Total cost to shopkeeper=6640x; SP of 16kg mix=2656=1.25*CP → CP=2124.80 → x=0.32, walnut price=300*0.32=96.', NULL, 8, 'high', 'high', 180, 'Forgetting to remove the lost quantity before computing the mixture selling price.'),
  ('CAT2018_QA_S1_20', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'SET_IEP', 'If among 200 students, 105 like pizza and 134 like burger, then the number of students who like only burger can possibly be', 'mcq', '23', '26', '96', '93', 'd', 'Only-burger count ranges from 134−105=29 (max overlap) to 134−(200−105)=39 subtracted differently; valid range is [29,95]; only 93 fits.', NULL, 5, 'medium', 'medium', 120, 'Not deriving both the minimum and maximum bounds on the overlap before checking options.'),
  ('CAT2018_QA_S1_21', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_RECURRENCE', 'If f(x+2) = f(x) + f(x+1) for all positive integers x, and f(11)=91, f(15)=617, then f(10) equals', 'tita', NULL, NULL, NULL, NULL, '54', 'Let f(10)=b; express f(12),f(13),f(14),f(15) in terms of b and f(11)=91: f(15)=455+3b=617 → b=54.', NULL, 6, 'medium', 'medium', 120, 'Arithmetic slips while chaining the recurrence forward through four steps.'),
  ('CAT2018_QA_S1_22', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'NS_MISC', 'In an apartment complex, the number of people aged 51 years and above is 30 and there are at most 39 people whose ages are below 51 years. The average age of all the people is 38 years. What is the largest possible average age, in years, of the people whose ages are below 51 years?', 'mcq', '27', '25', '26', '28', 'd', 'To maximise the below-51 average, minimise the above-51 average (all exactly 51) and use max count 39 below: (51*30+39x)/69=38 → x=28.', NULL, 6, 'high', 'high', 150, 'Not realising that using the maximum allowed count of 39 (not fewer) maximises the average.'),
  ('CAT2018_QA_S1_23', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'MIX_ALLIGATION', 'A trader sells 10 litres of a mixture of paints A and B, where the amount of B does not exceed that of A. Paint A costs Rs. 8 more per litre than B. If the trader sells the mixture for Rs. 264 at 10% profit, the highest possible cost of paint B, in Rs/litre, is', 'mcq', '16', '26', '20', '22', 'c', 'CP of mixture=240, so CP/litre=24. Highest CP of B occurs when volumes of A and B are equal: (x+x+8)/2=24 → x=20.', NULL, 6, 'medium', 'medium', 120, 'Not recognising that the maximum cost of B occurs at the boundary condition (equal volumes).'),
  ('CAT2018_QA_S1_24', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'GEO_QUAD', 'In a parallelogram ABCD of area 72 sq cm, sides CD and AD have lengths 9 cm and 16 cm. P is on CD with AP perpendicular to CD. The area, in sq cm, of triangle APD is', 'mcq', '32√3', '18√3', '24√3', '12√3', 'a', 'sin(∠ABC)=1/2 so ∠B=30°. Triangle APD is congruent to a right triangle with legs derived from BC=16 at 30°/60°, giving area 32√3.', NULL, 7, 'high', 'high', 150, 'Not spotting the congruent triangle pair (APD and CQB) that simplifies the computation.'),
  ('CAT2018_QA_S1_25', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_SPECIAL', 'If U² + (U − 2V − 1)² = −4V(U + V), then what is the value of U + 3V?', 'mcq', '0', '1/2', '−1/4', '1/4', 'c', 'Expanding and simplifying gives 2(U−1/2)²+8(V+1/4)²=0, so U=1/2, V=−1/4, and U+3V=−1/4.', NULL, 7, 'high', 'high', 150, 'Sign errors while expanding the squared bracket term.'),
  ('CAT2018_QA_S1_26', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'GEO_SECTOR', 'In a circle with center O and radius 1 cm, an arc AB makes an angle of 60° at O. C and D are on OA and OB with OC=OD, and area of triangle OCD is half that of the sector R. The length of OC, in cm, is', 'mcq', '(π/(4√3))^(1/2)', '(π/6)^(1/2)', '(π/(3√3))^(1/2)', '(π/4)^(1/2)', 'c', 'R = π/6. Area(OCD)=(1/2)x²sin60°=π/12, giving x²=π/(3√3), so OC=(π/(3√3))^(1/2).', NULL, 7, 'high', 'high', 150, 'Using the wrong angle (not 60°) inside the sine term for the triangle area.'),
  ('CAT2018_QA_S1_27', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'TSD_BASIC', 'The distance from A to B is 60 km. Partha and Narayan start from A at the same time towards B. Partha takes four hours more than Narayan to reach B, and reaches the mid-point two hours before Narayan reaches B. The speed of Partha, in km/hr, is', 'mcq', '6', '4', '3', '5', 'd', 'Let Partha take x hours for 60 km, Narayan x−4. Using the midpoint condition: x/2+2=x−4, solving gives x=12, so speed=60/12=5.', NULL, 6, 'high', 'high', 150, 'Confusing "two hours before Narayan reaches B" with "two hours before Narayan starts".'),
  ('CAT2018_QA_S1_28', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_GP', 'Let x, y, z be three positive reals in GP with x<y<z. If 5x, 16y, 12z are in AP, the common ratio of the GP is', 'mcq', '3/6', '1/6', '5/2', '3/2', 'c', 'With y=ar, z=ar², the AP condition gives 12r²−32r+5=0, roots 5/2 or 1/6. Since x<y<z needs r>1, ratio=5/2.', NULL, 6, 'medium', 'medium', 120, 'Accepting the root r=1/6 which violates x<y<z.'),
  ('CAT2018_QA_S1_29', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_EXP', 'Given that x^2018*y^2017 = 1/2, and x^2016*y^2019 = 8, then value of x²+y³ is', 'mcq', '31/4', '35/4', '37/4', '33/4', 'd', 'Dividing the two equations gives (y/x)²=16, so y/x=±4. Solving each case for x and y gives x²+y³=33/4 in the valid case.', NULL, 7, 'high', 'high', 180, 'Not checking both sign cases of y/x=±4 and picking the consistent one.'),
  ('CAT2018_QA_S1_30', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'PIPE_FILL', 'A tank is fitted with filling and draining pipes of equal individual rates. With 6 filling and 5 draining pipes it fills in 6 hours; with 5 filling and 6 draining it takes 60 hours. How many hours with one draining and two filling pipes?', 'tita', NULL, NULL, NULL, NULL, '10', '(6x−5y)*6=(5x−6y)*60 gives x=1.25y. Net rate of (2 fill, 1 drain)=1.5y; tank capacity=15y, so time=15y/1.5y=10 hours.', NULL, 6, 'high', 'high', 150, 'Sign errors when treating draining pipes as negative rate contributors.'),
  ('CAT2018_QA_S1_31', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_LOG_EQ', 'If log2(5 + log3 a) = 3 and log5(4a + 12 + log2 b) = 3, then a + b is equal to', 'mcq', '59', '40', '32', '67', 'a', 'First equation gives a=27. Substituting into second gives log2 b=5, b=32. So a+b=59.', NULL, 7, 'medium', 'medium', 150, 'Not simplifying the outer log correctly before solving for the inner variable.'),
  ('CAT2018_QA_S1_32', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'NS_MISC', 'A CAT aspirant appears for a certain number of tests. His average score increases by 1 if the first 10 tests are not considered, and decreases by 1 if the last 10 are not considered. If his average scores for the first 10 and last 10 tests are 20 and 30 respectively, the total number of tests is', 'tita', NULL, NULL, NULL, NULL, '60', 'From (n−10)(A+1)=nA−200 and (n−10)(A−1)=nA−300, solving simultaneously gives n=60.', NULL, 6, 'high', 'high', 150, 'Setting up the "excluding first/last 10" equations with the wrong sign on the average shift.'),
  ('CAT2018_QA_S1_33', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'NS_DIVISIBILITY', 'The number of integers x such that 0.25 ≤ 2^x ≤ 200 and 2^x + 2 is perfectly divisible by either 3 or 4, is', 'tita', NULL, NULL, NULL, NULL, '5', 'x ranges from −2 to 7. Checking 2^x+2 at each integer x for divisibility by 3 or 4 gives valid x = {0,1,2,4,6}, i.e. 5 values.', NULL, 7, 'high', 'high', 150, 'Missing the negative range of x allowed by 0.25 ≤ 2^x.'),
  ('CAT2018_QA_S1_34', 2018, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'PERC_BASIC', 'In an examination, the maximum possible score is N while the pass mark is 45% of N. A candidate obtains 36 marks, but falls short of the pass mark by 68%. Which one of the following is then correct?', 'mcq', 'N ≤ 200', '243 ≤ N ≤ 252', '201 ≤ N ≤ 242', 'N ≥ 253', 'b', '36 is 32% of the pass mark (100%−68%), so pass mark ≈112.5, and 0.45N=112.5 gives N=250, which falls in 243–252.', NULL, 6, 'medium', 'medium', 120, 'Treating "falls short by 68%" as an absolute mark deficit instead of a percentage of the pass mark.'),
  ('CAT2019_QA_S1_01', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'TSD_BASIC', 'Two cars travel the same distance starting at 10:00 am and 11:00 am, respectively, on the same day. They reach their common destination at the same time. If the first car travelled for at least 6 hours, the highest possible percentage by which the second car''s speed could exceed the first car''s is', 'mcq', '20', '30', '25', '10', 'a', 'First car takes ≥6 hrs, second takes 1 hr less. Max gap: first=6hr, second=5hr. Speed ratio (d/5)/(d/6)=6/5, i.e. 20% more.', NULL, 6, 'medium', 'medium', 120, 'Not recognising that minimising the first car''s time maximises the percentage gap.'),
  ('CAT2019_QA_S1_02', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_AP', 'If a1, a2, ... are in A.P., then 1/(√a1+√a2) + 1/(√a2+√a3) + ... + 1/(√an+√an+1) is equal to', 'mcq', 'n/(√a1+√an+1)', '(n-1)/(√a1+√an-1)', '(n-1)/(√a1+√an)', 'n/(√a1-√an+1)', 'a', 'Rationalising each term telescopes the sum to n(√an+1−√a1)/(an+1−a1) = n/(√a1+√an+1).', NULL, 6, 'high', 'medium', 150, 'Not rationalising before attempting to telescope the series.'),
  ('CAT2019_QA_S1_03', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'GEO_CIRCLE_CHORD', 'AB is a diameter of a circle of radius 5 cm. P and Q are points on the circle so that PB = 6 cm, and AP is twice AQ. The length, in cm, of QB is nearest to', 'mcq', '9.3', '7.8', '9.1', '8.5', 'c', 'AB=10, AP=√(10²−6²)=8, so AQ=4 and QB=√(10²−4²)≈9.17 ≈ 9.1.', NULL, 7, 'medium', 'medium', 150, 'Using AP directly instead of AQ=AP/2 when applying Pythagoras in triangle AQB.'),
  ('CAT2019_QA_S1_04', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_LOG', 'If (5.55)^x = (0.555)^y = 1000, then the value of 1/x − 1/y is', 'mcq', '1/3', '3', '1', '2/3', 'a', 'Taking log10: x(log555−2)=3 and y(log555−3)=3. Subtracting the reciprocals gives 1/x−1/y=1/3.', NULL, 6, 'high', 'high', 120, 'Sign errors when subtracting log555−2 and log555−3 based expressions.'),
  ('CAT2019_QA_S1_05', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'PERC_BASIC', 'The income of Amala is 20% more than that of Bimala and 20% less than that of Kamala. If Kamala''s income goes down by 4% and Bimala''s goes up by 10%, then the percentage by which Kamala''s income would exceed Bimala''s is nearest to', 'mcq', '31', '29', '28', '32', 'a', 'Bimala=100a, Amala=120a, Kamala=150a. New Kamala=144a, new Bimala=110a. Excess=(144−110)/110*100≈31%.', NULL, 6, 'medium', 'medium', 150, 'Applying percentage changes to the wrong base income.'),
  ('CAT2019_QA_S1_06', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'TSD_BASIC', 'The wheels of bicycles A and B have radii 30 cm and 40 cm. While traveling a certain distance, each wheel of A required 5000 more revolutions than each wheel of B. If bicycle B traveled this distance in 45 minutes, its speed, in km/hr, was', 'mcq', '18π', '14π', '16π', '12π', 'c', 'Distances equal: (5000+n)*60π = n*80π gives n=15000 revolutions for B, distance=15000*80π cm=12π km; speed=12π/(45/60)=16π.', NULL, 6, 'high', 'high', 150, 'Not converting revolutions to distance in consistent units before finding speed.'),
  ('CAT2019_QA_S1_07', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_QUAD_ROOT', 'The product of the distinct roots of |x² − x − 6| = x + 2 is', 'mcq', '−16', '-4', '-24', '-8', 'a', 'Splitting into cases (x²−x−6≥0 and <0) and solving gives roots x=4,2,−2, but checking validity leaves distinct roots 4 and −2 (or 4,2,−2 combos); the product of all distinct valid roots is −16.', NULL, 6, 'high', 'high', 150, 'Not checking each root against the sign condition used to remove the modulus.'),
  ('CAT2019_QA_S1_08', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'TSD_RELATIVE', 'In a race of three horses, the first beat the second by 11 metres and the third by 90 metres. If the second beat the third by 80 metres, what was the length, in metres, of the racecourse?', 'tita', NULL, NULL, NULL, NULL, '880', 'Setting speed ratios from the given margins and solving x/a=(x−11)/b etc. simultaneously gives race length x=880 m.', NULL, 7, 'high', 'high', 150, 'Mixing up which pair of runners each given margin refers to.'),
  ('CAT2019_QA_S1_09', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_RECURRENCE', 'If the population of a town is p in the beginning of any year then it becomes 3+2p in the beginning of the next year. If the population in the beginning of 2019 is 1000, the population in the beginning of 2034 will be', 'mcq', '(1003)^15 + 6', '(997)^15 − 3', '(997)*2^14 + 3', '(1003)*2^15 − 3', 'd', 'The recurrence unrolls to population after n years = 2^n(p+3)−3. For n=15, p=1000: 2^15*1003−3.', NULL, 6, 'high', 'high', 150, 'Losing track of the "−3" correction term while unrolling the recurrence.'),
  ('CAT2019_QA_S1_10', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_EXP', 'Consider a function f satisfying f(x+y)=f(x)f(y) where x,y are positive integers, and f(1)=2. If f(a+1)+f(a+2)+...+f(a+n)=16(2^n−1) then a is equal to', 'tita', NULL, NULL, NULL, NULL, '3', 'f(x)=2^x. Setting n=1 gives f(a+1)=16 → 2^(a+1)=16 → a=3.', NULL, 6, 'medium', 'medium', 150, 'Not simplifying the general sum first and instead testing arbitrary n values.'),
  ('CAT2019_QA_S1_11', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'SI_BASIC', 'Amala, Bina, and Gouri invest money in the ratio 3:4:5 with annual interest rates in the ratio 6:5:4. What is their total interest income (Rs) after a year, if Bina''s interest income exceeds Amala''s by Rs 250?', 'mcq', '6350', '6000', '7000', '7250', 'd', 'Interest incomes are proportional to 18,20,20 (principal*rate). Bina−Amala=2 units=250 → 1 unit=125. Total=58 units=7250.', NULL, 6, 'medium', 'medium', 150, 'Multiplying principal and rate ratios incorrectly when finding interest ratios.'),
  ('CAT2019_QA_S1_12', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_RECURRENCE', 'For any positive integer n, let f(n) = n(n+1) if n is even, and f(n) = n+3 if n is odd. If m is a positive integer such that 8f(m+1) − f(m) = 2, then m equals', 'tita', NULL, NULL, NULL, NULL, '10', 'Testing m even (so m+1 odd): 8(m+4)−m(m+1)=2 gives m²−7m−30=0 → m=10 (valid). The odd-m case gives no integer solution.', NULL, 7, 'high', 'high', 150, 'Not checking both parity cases (m even vs odd) before accepting a solution.'),
  ('CAT2019_QA_S1_13', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_SPECIAL', 'The product of two positive numbers is 616. If the ratio of the difference of their cubes to the cube of their difference is 157:3, then the sum of the two numbers is', 'mcq', '58', '85', '50', '95', 'c', 'Using a³−b³=(a−b)(a²+ab+b²) and the given ratio, algebra reduces to (a+b)²=2500, so a+b=50.', NULL, 7, 'high', 'high', 150, 'Not substituting ab=616 back into the expanded identity to simplify.'),
  ('CAT2019_QA_S1_14', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'TSD_AVG', 'One can use three transports at 10, 20, 30 kmph to reach from A to B. Amal took each mode for 1/3rd of his journey time; Bimal took each mode for 1/3rd of the total distance. The percentage by which Bimal''s travel time exceeds Amal''s is nearest to', 'mcq', '22', '20', '19', '21', 'a', 'Amal''s total distance=20t. Bimal''s time for equal distance splits sums to 11t/9. Ratio (11t/9)/t=11/9, exceeding by about 22%.', NULL, 7, 'high', 'high', 180, 'Confusing "equal time" splits with "equal distance" splits between the two travellers.'),
  ('CAT2019_QA_S1_15', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'PERC_BASIC', 'Meena scores 40% in an exam and after review, even though her score increases by 50%, she fails by 35 marks. If her post-review score is increased by 20%, she will have 7 marks more than the passing score. The percentage score needed for passing is', 'mcq', '60', '80', '70', '75', 'c', 'Let max marks=100a. Post-review=60a=passing−35; 1.2*(60a)=passing+7. Solving gives a=3.5, passing=245/350=70%.', NULL, 6, 'high', 'high', 150, 'Applying the 20% increase to the original score instead of the already-revised score.'),
  ('CAT2019_QA_S1_16', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'SI_BASIC', 'A person invested Rs 15 lakh; part in a fixed deposit at 6%, rest in two deposits in ratio 2:1 at 4% and 3%. If total annual interest is Rs 76000, the amount (Rs lakh) in the fixed deposit was', 'tita', NULL, NULL, NULL, NULL, '9', 'With fixed deposit F, remaining (15−F) split 2:1: total interest=0.06F+0.04*(2/3)(15−F)+0.03*(1/3)(15−F)=0.76, solving gives F=9.', NULL, 6, 'medium', 'medium', 150, 'Splitting the remaining amount in the wrong ratio direction (3:2 instead of 2:1).'),
  ('CAT2019_QA_S1_17', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'SET_IEP', 'A club has 256 members: 144 play football, 123 tennis, 132 cricket; 58 play both football & tennis, 25 both cricket & tennis, 63 both football & cricket. Every member plays at least one game. The number who play only tennis is', 'mcq', '38', '32', '45', '43', 'd', 'Using inclusion-exclusion to find the triple overlap (=3) then subtracting pairwise-only overlaps gives only-tennis = 123−58−25+3 = 43.', NULL, 7, 'high', 'high', 180, 'Forgetting to add back the triple-overlap term when computing "only" counts.'),
  ('CAT2019_QA_S1_18', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_SERIES_SPECIAL', 'If a1+a2+a3+....+an = 3(2^(n+1) − 2), for every n≥1, then a11 equals', 'tita', NULL, NULL, NULL, NULL, '6144', 'a11 = S11 − S10 = 3(2^12−2) − 3(2^11−2) = 3*2^11 = 6144.', NULL, 6, 'medium', 'medium', 120, 'Computing S11 or S10 with an arithmetic slip in the exponent.'),
  ('CAT2019_QA_S1_19', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'GEO_TRIG_IDENTITY', 'The number of the real roots of the equation 2cos(x(x+1)) = 2^x + 2^(−x) is', 'mcq', '2', '1', 'infinite', '0', 'b', 'LHS max is 2 (cosine bound), RHS min is 2 by AM-GM, equal only when both extremes hit: cos=1 needs x(x+1)=0, and RHS=2 needs x=0. Only x=0 satisfies both.', NULL, 7, 'high', 'high', 150, 'Not checking that both boundary conditions must hold simultaneously, not just one.'),
  ('CAT2019_QA_S1_20', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'TW_COMBINED', 'At their usual efficiency, A and B together finish a task in 12 days. If A worked half as efficiently and B thrice as efficiently, it would take 9 days. How many days would A alone take at usual efficiency?', 'mcq', '36', '24', '18', '12', 'c', '12(a+b)=1 and 9(a/2+3b)=1. Solving simultaneously gives a=1/18, so A alone takes 18 days.', NULL, 6, 'medium', 'medium', 150, 'Setting up the modified-efficiency equation with the multipliers on the wrong worker.'),
  ('CAT2019_QA_S1_21', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'PERC_BASIC', 'In a class, 60% of the students are girls, rest boys. There are 30 more girls than boys. If 68% of the students, including 30 boys, pass, the percentage of girls who do not pass is', 'tita', NULL, NULL, NULL, NULL, '20', 'Girls=90, boys=60 (from 60x−40x=30 → x=1.5). Girls passing=68%*150−30=72. Girls not passing=90−72=18, i.e. 20% of girls.', NULL, 6, 'high', 'high', 150, 'Forgetting to subtract the 30 passing boys before finding girls who passed.'),
  ('CAT2019_QA_S1_22', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'GEO_CIRCLE_CHORD', 'In a circle of radius 11 cm, CD is a diameter and AB a chord of length 20.5 cm. If AB and CD intersect at E inside the circle and CE=7 cm, the difference of the lengths of BE and AE, in cm, is', 'mcq', '2.5', '1.5', '3.5', '0.5', 'd', 'By the intersecting chords theorem, AE*BE=CE*DE=7*15=105. With AE+BE=20.5, solving the quadratic gives AE,BE={10,10.5}, difference=0.5.', NULL, 7, 'high', 'high', 180, 'Not using DE=22−CE=15 correctly when applying the intersecting-chords product.'),
  ('CAT2019_QA_S1_23', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'PL_CP_SP', 'On selling a pen at 5% loss and a book at 15% gain, Karim gains Rs. 7. If he sells the pen at 5% gain and the book at 10% gain, he gains Rs. 13. What is the cost price of the book in Rupees?', 'mcq', '95', '85', '80', '100', 'c', 'With pen CP=100p, book CP=100b: −5p+15b=7 and 5p+10b=13. Adding gives 25b=20, so book CP=80.', NULL, 6, 'medium', 'medium', 120, 'Sign error on the loss term when setting up the first profit equation.'),
  ('CAT2019_QA_S1_24', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'MIX_ALLIGATION', 'A chemist mixes liquids 1 and 2 (1 kg/L and 0.8 kg/L). If half a litre of the mixture weighs 480 gm, the percentage of liquid 1 in the mixture, by volume, is', 'mcq', '80', '70', '85', '75', 'a', 'Mixture density=960 g/L. By alligation, ratio of liquid1:liquid2=(960−800):(1000−960)=4:1, so liquid1=80%.', NULL, 5, 'medium', 'low', 120, 'Forgetting to scale the half-litre weight up to a per-litre density before applying alligation.'),
  ('CAT2019_QA_S1_25', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'NS_MISC', 'Ramesh and Gautam are among 22 students who write an exam. Ramesh scores 82.5. The average of the 21 students other than Gautam is 62. The average of all 22 is one more than the average of the 21 other than Ramesh. The score of Gautam is', 'mcq', '53', '51', '48', '49', 'b', 'Let avg of 21 excluding Ramesh = a; Ramesh''s score = a+22 = 82.5 → a=60.5. Total of 22 = 22*61.5=1353; subtracting the 21 (excl. Gautam) sum of 1302 gives Gautam=51.', NULL, 7, 'high', 'high', 180, 'Confusing "average excluding Ramesh" with "average excluding Gautam" in the setup.'),
  ('CAT2019_QA_S1_26', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_INDICES', 'If m and n are integers such that (√2)^19 * 3^4 * 4^2 * 9^m * 8^n = 3^n * 16^m * (64)^(1/4), then m is', 'mcq', '-20', '-24', '-12', '-16', 'c', 'Expressing both sides in base 2 and 3 and comparing exponents gives two equations in m,n; solving simultaneously yields m=−12.', NULL, 7, 'high', 'high', 180, 'Errors converting mixed bases (4, 9, 8, 16, 64) into consistent powers of 2 and 3.'),
  ('CAT2019_QA_S1_27', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'TW_COMBINED', 'Three men and eight machines finish a job in half the time taken by three machines and eight men. If two machines can finish the job in 13 days, how many men can finish the job in 13 days?', 'tita', NULL, NULL, NULL, NULL, '13', 'From 3a+8b=2(3b+8a), we get 13a=2b, i.e. work of 13 men/day = work of 2 machines/day. So 13 men match 2 machines'' 13-day performance.', NULL, 7, 'high', 'high', 150, 'Not spotting the direct man-machine equivalence hidden in the efficiency equation.'),
  ('CAT2019_QA_S1_28', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'GEO_POLY', 'Corners are cut off from an equilateral triangle T to produce a regular hexagon H. The ratio of the area of H to the area of T is', 'mcq', '2 : 3', '4 : 5', '5 : 6', '3 : 4', 'a', 'Dividing the triangle into 9 equal small triangles, the hexagon covers 6 of them, giving a ratio of 6:9 = 2:3.', NULL, 6, 'medium', 'low', 120, 'Miscounting how many of the small unit triangles fall inside the hexagon versus the corners.'),
  ('CAT2019_QA_S1_29', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_LOG_EQ', 'Let x and y be positive reals such that log5(x+y) + log5(x−y) = 3, and log2 y − log2 x = 1 − log2 3. Then xy equals', 'mcq', '150', '25', '100', '250', 'a', 'The first equation gives log₅[(x+y)(x−y)] = 3, so x² − y² = 5³ = 125. The second gives log₂(y/x) = log₂(2/3), so y/x = 2/3, i.e. x = 3y/2. Substituting: (9y²/4) − y² = 5y²/4 = 125 ⇒ y² = 100 ⇒ y = 10 (positive), and x = 15. Therefore xy = 150.', NULL, 7, 'high', 'high', 180, 'Misconverting the second logarithmic equation into the ratio x/y.'),
  ('CAT2019_QA_S1_30', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_INEQ_MOD', 'Let S be the set of all points (x,y) such that |x|+|y| ≤ 2 and |x| ≥ 1. The area, in square units, of the region represented by S equals', 'tita', NULL, NULL, NULL, NULL, '2', 'The region forms two small triangles (one on each side, |x|≥1) each of area 1/2*1*1, four such triangles total area 2.', NULL, 6, 'medium', 'medium', 150, 'Not restricting to |x|≥1 and instead computing the area of the full diamond |x|+|y|≤2.'),
  ('CAT2019_QA_S1_31', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'MOD_SELECT', 'With rectangular axes, the number of paths from (1,1) to (8,10) via (4,6), where each step is to (x,y+1) or (x+1,y), is', 'tita', NULL, NULL, NULL, NULL, '3920', 'Paths (1,1)→(4,6) = C(8,3)=56; paths (4,6)→(8,10) = C(8,4)=70. Total = 56*70 = 3920.', NULL, 7, 'high', 'high', 150, 'Using the wrong total step count (sum of x and y differences) for each leg of the path.'),
  ('CAT2019_QA_S1_32', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'GEO_CUBE', 'If the rectangular faces of a brick have their diagonals in the ratio 3 : 2√3 : √15, then the ratio of the length of the shortest edge of the brick to that of its longest edge is', 'mcq', '√3 : 2', '1 : √3', '2 : √5', '√2 : √3', 'b', 'Setting a²+b²=9k, b²+c²=12k, c²+a²=15k and solving gives a²=6k,b²=3k,c²=9k, so shortest:longest = √3k : 3√k = 1:√3.', NULL, 7, 'high', 'high', 180, 'Not adding all three equations first to isolate a²+b²+c² before solving individually.'),
  ('CAT2019_QA_S1_33', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'ALG_INEQ_MOD', 'The number of solutions to the equation |x|(6x² + 1) = 5x² is', 'tita', NULL, NULL, NULL, NULL, '5', 'Splitting for x<0, x=0, x>0 gives quadratics (3x+1)(2x+1)=0 and (3x−1)(2x−1)=0 plus x=0, totalling 5 solutions.', NULL, 6, 'high', 'high', 150, 'Forgetting to separately verify x=0 as a valid solution alongside the two quadratic cases.'),
  ('CAT2019_QA_S1_34', 2019, 'Slot 1', 'Cracku (CAT Official)', TRUE, 'GEO_COORD_CIRCLE', 'Let T be the triangle formed by the line 3x+5y−45=0 and the coordinate axes. Let the circumcircle of T have radius L. The integer closest to L is', 'tita', NULL, NULL, NULL, NULL, '9', 'Intercepts are (15,0) and (0,9), forming a right triangle at origin. Circumradius = half the hypotenuse = (1/2)√(15²+9²) ≈ 8.74, closest integer 9.', NULL, 6, 'medium', 'medium', 150, 'Forgetting that for a right triangle, the circumradius is simply half the hypotenuse.'),
  ('CAT2019_QA_S2_01', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'NS_MISC', 'The average of 30 integers is 5. Among these 30, exactly 20 do not exceed 5. What is the highest possible value of the average of these 20 integers?', 'mcq', '3.5', '5', '4.5', '4', 'c', 'Total sum=150. To maximise the 20-integer average, minimise the other 10 (each at least 6): sum of 10 ≥60, so sum of 20 ≤90, average ≤4.5.', NULL, 5, 'medium', 'medium', 120, 'Forgetting the other 10 integers must each be at least 6 (strictly exceeding 5).'),
  ('CAT2019_QA_S2_02', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'CI_ANNUAL', 'Amal invests Rs 12000 at 8% compounded annually, and Rs 10000 at 6% compounded semi-annually, both for one year. Bimal invests at 7.5% simple interest for one year. If Amal and Bimal get the same interest, the amount invested by Bimal is', 'tita', NULL, NULL, NULL, NULL, '20920', 'Amal''s total interest = 12000*0.08 + 10000*(1.03²−1) = 1569. Bimal''s interest=0.075*Investment=1569 gives investment=20920.', NULL, 6, 'medium', 'medium', 150, 'Using annual compounding instead of semi-annual for the second investment.'),
  ('CAT2019_QA_S2_03', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'ALG_BASIC', 'What is the largest positive integer n such that (n²+7n+12)/(n²−n−12) is also a positive integer?', 'mcq', '6', '16', '8', '12', 'd', 'Simplifying gives (n+4)/(n−4) = 1+8/(n−4), maximised (as an integer) when n−4=8, i.e. n=12.', NULL, 6, 'medium', 'medium', 150, 'Not factoring both quadratics fully before cancelling the common (n+3) term.'),
  ('CAT2019_QA_S2_04', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'NS_FACTORS', 'How many pairs (m, n) of positive integers satisfy the equation m² + 105 = n²?', 'tita', NULL, NULL, NULL, NULL, '4', '(n−m)(n+m)=105. Factor pairs of 105 with matching parity give 4 valid positive-integer solutions for (m,n).', NULL, 6, 'medium', 'medium', 150, 'Including factor pairs where n−m and n+m have different parity (impossible for integer m,n).'),
  ('CAT2019_QA_S2_05', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'TSD_CIRCULAR', 'Two ants A and B start from a point P on a circle, A moving clockwise, B anti-clockwise. They meet for the first time at 10:00 am when A has covered 60% of the track. If A returns to P at 10:12 am, then B returns to P at', 'mcq', '10:25 am', '10:45 am', '10:18 am', '10:27 am', 'd', 'A covers remaining 40% in 12 min → full lap 30 min. B covers 40% by 10:00am (18 min for its 60% remaining), so B''s lap=45min, returning at 10:27am.', NULL, 6, 'high', 'high', 150, 'Assuming A and B have the same speed instead of deriving each speed from the meeting point.'),
  ('CAT2019_QA_S2_06', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'ALG_RECURRENCE', 'Let a1, a2, ... be integers such that a1−a2+a3−a4+...+(−1)^(n−1)an = n, for all n≥1. Then a51+a52+...+a1023 equals', 'mcq', '0', '1', '10', '-1', 'b', 'Read off successive values of n. n=1: a1 = 1. n=2: a1 − a2 = 2 ⇒ a2 = −1. n=3: 1 + 1 + a3 = 3 ⇒ a3 = 1. n=4: 1 + 1 + 1 − a4 = 4 ⇒ a4 = −1. So every odd-indexed term is 1 and every even-indexed term is −1. From index 51 to 1023 there are 487 odd indices (51, 53, …, 1023) and 486 even ones (52, 54, …, 1022). Sum = 487 − 486 = 1.', NULL, 7, 'high', 'high', 180, 'Miscounting the number of odd vs even indexed terms within the summation range.'),
  ('CAT2019_QA_S2_07', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'GEO_CIRCLE_TANGENT', 'Two circles, each of radius 4 cm, touch externally. Each is touched externally by a third circle. If these three circles have a common tangent, the radius of the third circle, in cm, is', 'mcq', '1/√2', 'π/3', '√2', '1', 'd', 'Using the common-tangent triangle relation √((8+r)r) + r = 4 leads to r = 1.', NULL, 6, 'high', 'high', 150, 'Misapplying the tangent-length relation between the two large circles and the small circle.'),
  ('CAT2019_QA_S2_08', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'ALG_QUAD_ROOT', 'Let A be a real number. The roots of x² − 4x − log2(A) = 0 are real and distinct if and only if', 'mcq', 'A > 1/16', 'A < 1/16', 'A < 1/8', 'A > 1/8', 'a', 'Discriminant > 0: 16 + 4log2(A) > 0 → log2(A) > −4 → A > 1/16.', NULL, 6, 'medium', 'medium', 120, 'Sign error while isolating log2(A) from the discriminant inequality.'),
  ('CAT2019_QA_S2_09', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'ALG_QUAD_ROOT', 'The quadratic equation x²+bx+c=0 has two roots 4a and 3a, where a is an integer. Which of the following is a possible value of b²+c?', 'mcq', '3721', '361', '427', '549', 'd', 'b²+c = 49a²+12a² = 61a². Testing options, only 549/61=9 gives an integer a=3.', NULL, 6, 'medium', 'medium', 150, 'Not checking that the resulting a² must be a perfect square from an integer a.'),
  ('CAT2019_QA_S2_10', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'GEO_TRI_BASIC', 'The base of a regular pyramid is a square and each of the other four sides is an equilateral triangle, side 20 cm. The vertical height of the pyramid, in cm, is', 'mcq', '12', '10√2', '8√3', '5√5', 'b', 'Because every lateral face is equilateral with side 20, each lateral edge from the apex to a base corner is also 20. The base is a square of side 20, so its diagonal is 20√2 and the distance from the centre to a corner is 10√2. The apex, the centre, and a base corner form a right triangle: h² + (10√2)² = 20² ⇒ h² = 400 − 200 = 200 ⇒ h = 10√2.', NULL, 6, 'high', 'high', 150, 'Using the side of the square instead of the half-diagonal as the base offset from apex projection.'),
  ('CAT2019_QA_S2_11', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'GEO_TRI_BASIC', 'Let ABC be a right-angled triangle with hypotenuse BC of length 20 cm. If AP is perpendicular to BC, the maximum possible length of AP, in cm, is', 'mcq', '10', '5', '8√2', '6√2', 'a', 'AP=(AB*AC)/BC is maximised when AB=AC (isosceles right triangle), giving AP=10.', NULL, 6, 'medium', 'medium', 120, 'Not recognising the AM-GM style maximisation condition for AB*AC given AB²+AC²=400.'),
  ('CAT2019_QA_S2_12', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'ALG_LOG', 'If x is a real number, then √(loge((4x−x²)/3)) is a real number if and only if', 'mcq', '1 ≤ x ≤ 3', '1 ≤ x ≤ 2', '−1 ≤ x ≤ 3', '−3 ≤ x ≤ 3', 'a', 'Need (4x−x²)/3 ≥ 1, i.e. x²−4x+3 ≤ 0, giving 1 ≤ x ≤ 3.', NULL, 6, 'medium', 'medium', 120, 'Requiring only positivity of the log argument instead of the log itself being ≥0.'),
  ('CAT2019_QA_S2_13', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'ALG_EXP', 'If 5^x − 3^y = 13438 and 5^(x−1) + 3^(y+1) = 9686, then x + y equals', 'tita', NULL, NULL, NULL, NULL, '13', 'Multiplying the second equation by 5 and combining with the first isolates 3^y=2187 (y=7), then 5^x=15625 (x=6). x+y=13.', NULL, 6, 'high', 'high', 150, 'Arithmetic slip when eliminating 5^x between the two given equations.'),
  ('CAT2019_QA_S2_14', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'MIX_REPLACEMENT', 'Vessels A, B, C each contain 500 ml of salt solution of strengths 10%, 22%, 32%. 100 ml of A is transferred to B, then 100 ml of B to C, then 100 ml of C to A. The strength, in percentage, of the resulting solution in vessel A is', 'mcq', '15', '13', '12', '14', 'd', 'Tracking salt content through each transfer step-by-step gives final salt in A = 70 ml out of 500 ml, i.e. 14%.', NULL, 7, 'high', 'high', 180, 'Not tracking the changing total volume/concentration in B and C after each successive transfer.'),
  ('CAT2019_QA_S2_15', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'TSD_RELATIVE', 'A cyclist leaves A at 10 am and reaches B at 11 am. From 10:01 am, every minute a motorcycle leaves A towards B; forty-five reach B by 11 am. If the cyclist had doubled his speed, how many motorcycles would have reached B by then?', 'mcq', '22', '23', '15', '20', 'c', 'Each motorcycle takes 15 minutes (45th one leaves at 10:45, arrives 11:00). If cyclist doubles speed, he arrives at 10:30, so 15 motorcycles (taking 15 min each) would have reached by then.', NULL, 6, 'high', 'high', 150, 'Not recomputing the cyclist''s new arrival time before counting motorcycles.'),
  ('CAT2019_QA_S2_16', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'GEO_CYL', 'A man uses 405 cc iron, 783 cc aluminium, 351 cc copper to make cylinders of each metal (all same volume, radius 3 cm), minimising total cylinder count. The total surface area of all cylinders, in sq cm, is', 'mcq', '1026(1+π)', '8464π', '928π', '1044(4+π)', 'a', 'Volume per cylinder = HCF(405,783,351)=27, giving 15+29+13=57 cylinders of height 1 cm (from πr²h=27, r=3). Total surface area=57(2πrh+2πr²)=1026(1+π).', NULL, 7, 'high', 'high', 180, 'Using the wrong HCF as the common cylinder volume, inflating or reducing the cylinder count.'),
  ('CAT2019_QA_S2_17', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'ALG_EXP', 'The real root of the equation 2^(6x) + 2^(3x+2) − 21 = 0 is', 'mcq', 'log2(9)', 'log2(3)/3', 'log2(27)', 'log2(7)/3', 'b', 'Let v=2^(3x): v²+4v−21=0 → v=3 (rejecting −7). So 3x=log2(3), x=log2(3)/3.', NULL, 6, 'medium', 'medium', 150, 'Accepting the negative root v=−7 as valid for 2^(3x).'),
  ('CAT2019_QA_S2_18', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'NS_FACTORS', 'How many factors of 2^4 × 3^5 × 10^4 are perfect squares which are greater than 1?', 'tita', NULL, NULL, NULL, NULL, '44', 'Rewriting as 2^8*3^5*5^4, perfect square factors need even exponents: 5 choices for 2, 3 for 3, 3 for 5, total 45 minus the factor "1" itself = 44.', NULL, 6, 'high', 'high', 150, 'Forgetting to convert 10^4 into its prime factors (2^4*5^4) before counting.'),
  ('CAT2019_QA_S2_19', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'NS_MISC', 'In a six-digit number, the sixth digit is the sum of the first three, the fifth is the sum of the first two, the third equals the first, the second is twice the first, and the fourth is the sum of the fifth and sixth. The largest possible value of the fourth digit is', 'tita', NULL, NULL, NULL, NULL, '7', 'Letting first digit=A, digit D=7A. Since D must be a single digit and A≠0 (six-digit number) or 2 (D becomes two digits), A=1 gives the largest valid D=7.', NULL, 7, 'high', 'high', 150, 'Not checking that A=2 would make the fourth digit a two-digit value, which is invalid.'),
  ('CAT2019_QA_S2_20', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'TSD_RELATIVE', 'John jogs on track A at 6 kmph and Mary jogs on track B at 7.5 kmph. Total length of tracks A and B is 325 metres. While John makes 9 rounds of A, Mary makes 5 rounds of B. In how many seconds will Mary make one round of track A?', 'tita', NULL, NULL, NULL, NULL, '48', 'Equal times: 9a/6 = 5(325−a)/7.5 solving gives a=100 m (track A). Mary''s time for 100m at 7.5kmph = 48 seconds.', NULL, 6, 'high', 'high', 150, 'Not setting the two round-times equal before solving for the individual track lengths.'),
  ('CAT2019_QA_S2_21', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'PERC_SUCCESSIVE', 'In 2010, a library had 11500 books (fiction+nonfiction). In 2015, it had 12760, with 10% increase in fiction and 12% in nonfiction. How many fiction books were in the library in 2015?', 'mcq', '6160', '6600', '6000', '5500', 'b', 'With 100a+100b=11500 and 110a+112b=12760, solving gives a=60, so fiction in 2015 = 110*60 = 6600.', NULL, 6, 'medium', 'medium', 150, 'Applying both percentage increases to the same base instead of solving the simultaneous equations.'),
  ('CAT2019_QA_S2_22', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'TW_WAGES', 'John gets Rs 57/hr regular and Rs 114/hr overtime. He works 172 hours total, and his overtime income is 15% of his regular income. For how many hours did he work overtime?', 'tita', NULL, NULL, NULL, NULL, '12', 'Let regular hours=a: 0.15*57a = 114*(172−a). Solving gives a=160, so overtime hours=172−160=12.', NULL, 6, 'medium', 'medium', 150, 'Applying the 15% relationship to total hours instead of total income.'),
  ('CAT2019_QA_S2_23', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'ALG_SERIES_SPECIAL', 'If (2n+1)+(2n+3)+(2n+5)+...+(2n+47) = 5280, then what is the value of 1+2+3+...+n?', 'tita', NULL, NULL, NULL, NULL, '4851', 'The terms 2n+1, 2n+3, …, 2n+47 have odd offsets 1 through 47, so there are 24 of them. Sum = 24(2n) + (1 + 3 + ⋯ + 47) = 48n + 24² = 48n + 576 = 5280 ⇒ 48n = 4704 ⇒ n = 98. Then 1 + 2 + ⋯ + 98 = 98 × 99/2 = 4851.', NULL, 6, 'medium', 'medium', 150, 'Miscounting the number of terms in the given arithmetic series.'),
  ('CAT2019_QA_S2_24', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'PL_CP_SP', 'A shopkeeper sells two tables, each procured at cost price p, to Amal and Asim at 20% profit and 20% loss respectively. Amal sells his to Bimal at 30% profit; Asim sells his to Barun at 30% loss. If Bimal and Barun pay x and y, then (x−y)/p equals', 'mcq', '1', '1.2', '0.50', '0.7', 'a', 'x=1.2p*1.3=1.56p; y=0.8p*0.7=0.56p. (x−y)/p = 1.', NULL, 6, 'medium', 'medium', 150, 'Applying the second profit/loss percentage to the original price p instead of the intermediate selling price.'),
  ('CAT2019_QA_S2_25', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'GEO_TRI_CENTERS', 'In a triangle ABC, medians AD and BE are perpendicular, with lengths 12 cm and 9 cm. The area of triangle ABC, in sq cm, is', 'mcq', '78', '80', '72', '68', 'c', 'Centroid divides medians 2:1 (AG=8, GD=4, BG=6, GE=3). Area(ABC)=2*Area(ABD)=2*(Area AGB+Area BGD)=2*(24+12)=72.', NULL, 7, 'high', 'high', 150, 'Not using the 2:1 centroid ratio correctly to split the medians before computing sub-triangle areas.'),
  ('CAT2019_QA_S2_26', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'ALG_AP', 'The number of common terms in the two sequences: 15,19,23,27,...,415 and 14,19,24,29,...,464 is', 'mcq', '21', '20', '18', '19', 'b', 'First common term is 19; common difference = LCM(4,5)=20. Terms 19+(n−1)*20 ≤ 415 gives n up to 20.', NULL, 6, 'medium', 'medium', 150, 'Using the wrong common difference (not taking the LCM of the two individual differences).'),
  ('CAT2019_QA_S2_27', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'ALG_SPECIAL', 'Let a,b,x,y be real numbers such that a²+b²=25, x²+y²=169, and ax+by=65. If k=ay−bx, then', 'mcq', '0 < k ≤ 5/13', 'k > 5/13', 'k = 5/13', 'k = 0', 'd', 'Using (ax+by)²+(ay−bx)²=(a²+b²)(x²+y²), k²=65²−(25*169)=0, so k=0.', NULL, 7, 'high', 'high', 180, 'Not recognising the Lagrange identity connecting ax+by and ay−bx to the two magnitudes.'),
  ('CAT2019_QA_S2_28', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'PL_CP_SP', 'Mukesh purchased 10 bicycles in 2017, all at the same price. He sold six at 25% profit and four at 25% loss, for a total profit of Rs. 2000. His purchase price of a bicycle, in Rupees, was', 'mcq', '6000', '8000', '4000', '2000', 'c', 'SP total = 1.25b*6 + 0.75b*4 = 10.5b, profit = 0.5b = 2000, so b (cost per bicycle) = 4000.', NULL, 5, 'medium', 'low', 120, 'Averaging the 25% profit and loss to zero instead of computing net profit from the 6:4 split.'),
  ('CAT2019_QA_S2_29', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'PERC_BASIC', 'In an examination, the score of A was 10% less than B, B was 25% more than C, and C was 20% less than D. If A scored 72, the score of D was', 'tita', NULL, NULL, NULL, NULL, '80', 'A=0.9B, B=1.25C, C=0.8D → A=0.9*1.25*0.8*D=0.9D. 0.9D=72 gives D=80.', NULL, 6, 'medium', 'medium', 150, 'Chaining the percentage relationships in the wrong order or direction.'),
  ('CAT2019_QA_S2_30', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'RATIO_BASIC', 'The salaries of Ramesh, Ganesh and Rajesh were in ratio 6:5:7 in 2010, and 3:4:3 in 2015. If Ramesh''s salary increased by 25% during 2010-2015, the percentage increase in Rajesh''s salary is closest to', 'mcq', '10', '7', '9', '8', 'b', 'With Ramesh 6x→3y and 3y=1.25*6x gives y=2.5x. Rajesh 7x→3y=7.5x, an increase of 0.5x/7x≈7%.', NULL, 6, 'high', 'high', 150, 'Forgetting that the ratio scale factor (x to y) changes between the two years.'),
  ('CAT2019_QA_S2_31', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'GEO_POLY', 'Let A and B be two regular polygons with a and b sides. If b=2a and each interior angle of B is 3/2 times each interior angle of A, then each interior angle, in degrees, of a regular polygon with a+b sides is', 'tita', NULL, NULL, NULL, NULL, '150', 'Setting up the interior-angle formula ratio with b=2a gives a=4, b=8. Interior angle of a 12-sided polygon = (12−2)*180/12 = 150.', NULL, 7, 'high', 'high', 150, 'Plugging b=2a into the angle formula before simplifying, leading to algebra errors.'),
  ('CAT2019_QA_S2_32', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'ALG_SPECIAL', 'Let f be a function such that f(mn)=f(m)f(n) for every positive integers m,n. If f(1),f(2),f(3) are positive integers, f(1)<f(2), and f(24)=54, then f(18) equals', 'tita', NULL, NULL, NULL, NULL, '12', 'f(1)=1. f(24)=f(2)³f(3)=54=27*2 gives f(2)=3, f(3)=2. f(18)=f(2)f(3)²=3*4=12.', NULL, 7, 'high', 'high', 180, 'Not factoring 24 and 18 correctly into powers of 2 and 3 before applying multiplicativity.'),
  ('CAT2019_QA_S2_33', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'TW_COMBINED', 'Anil alone can do a job in 20 days, Sunil in 40 days. Anil starts, and after 3 days Sunil joins. After a few more days, Bimal joins them and they finish together. If Bimal did 10% of the job, in how many days was the job done?', 'mcq', '12', '13', '15', '14', 'b', 'Take the job as 40 units, so Anil does 2/day and Sunil 1/day. Bimal contributes 10% of 40 = 4 units. Let the job take T days in total. Anil works all T days (2T units) and Sunil works T − 3 days (T − 3 units). Then 2T + (T − 3) + 4 = 40, so 3T + 1 = 40, giving T = 13 days.', NULL, 6, 'high', 'high', 150, 'Not tracking the changing combined rate as each worker joins at a different day.'),
  ('CAT2019_QA_S2_34', 2019, 'Slot 2', 'Cracku (CAT Official)', TRUE, 'RATIO_BASIC', 'In an examination, Rama''s score was one-twelfth of the sum of the scores of Mohan and Anjali. After review, each score increased by 6. The revised scores of Anjali, Mohan, and Rama were in ratio 11:10:3. Then Anjali''s score exceeded Rama''s score by', 'mcq', '26', '32', '35', '24', 'b', 'With revised scores 11x,10x,3x and original r=(m+a)/12, solving the resulting equation gives x=4. Anjali−Rama (revised) = 8x = 32.', NULL, 6, 'high', 'high', 180, 'Using original (pre-review) scores instead of revised scores when computing the final difference.'),
  ('CAT2017_QA_S2_01', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'NS_MISC', 'The numbers 1 to 9 are arranged in a 3x3 grid so every row, column and diagonal has the same sum. If the top-left entry is 6 and the top-right entry is 2, find the bottom-middle entry.', 'tita', NULL, NULL, NULL, NULL, '3', 'Total of 1-9 is 45, so each row/column/diagonal sums to 15. With 6 and 2 fixed in the top row, testing the centre value that keeps all lines consistent (centre=5) forces the grid to 6,7,2 / 1,5,9 / 8,3,4, giving bottom-middle = 3.', NULL, 6, 'medium', 'high', 120, 'Trying random fills instead of first fixing the magic constant (15) and the centre value.'),
  ('CAT2017_QA_S2_02', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'TSD_RELATIVE', 'In a 10 km race, A beats B by 1 km and B beats C by 1 km, with all three running at uniform speed. By how many metres does A beat C?', 'tita', NULL, NULL, NULL, NULL, '1900', 'Speed(A):Speed(B)=10:9 and Speed(B):Speed(C)=10:9, so Speed(A):Speed(B):Speed(C)=100:90:81. When A covers 10 km, C covers 8.1 km, so A beats C by 1.9 km = 1900 m.', NULL, 6, 'medium', 'medium', 90, 'Wrongly adding the two 1 km leads (assuming A beats C by 2 km) instead of combining the speed ratios.'),
  ('CAT2017_QA_S2_03', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'MIX_ALLIGATION', 'Bottle 1 has milk:water = 7:2 and Bottle 2 has milk:water = 9:4. In what ratio should the two bottles be combined to get a milk:water ratio of 3:1?', 'mcq', '27:14', '27:13', '27:16', '27:18', 'b', 'Milk fractions are 7/9 and 9/13. Mixing bottle volumes in ratio X:1 and setting the resulting milk fraction to 3/4 gives 91X+81=78X+108, so X=27/13.', NULL, 6, 'medium', 'medium', 120, 'Using weight fractions of water instead of milk, or mixing up which liquid the target ratio 3:1 refers to.'),
  ('CAT2017_QA_S2_04', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'TSD_BASIC', 'Arun drives to his hostel at 60 mph. Returning, he covers half the distance at 25 mph then takes a 5-mile-longer bypass at 50 mph. The return trip takes 30 minutes more than the onward trip. Find the total distance travelled.', 'mcq', '55 miles', '60 miles', '65 miles', '70 miles', 'c', 'Let one-way distance be 2x. Onward time = 2x/60. Return time = x/25 + (x+5)/50. Setting return = onward + 0.5 gives x = 15, so total distance = 4x+5 = 65 miles.', NULL, 7, 'high', 'medium', 150, 'Forgetting that the bypass road only adds 5 miles to the second half, not the whole return trip.'),
  ('CAT2017_QA_S2_05', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'PERC_SUCCESSIVE', 'In a factory, 15% of shirts are defective and 20% of the remaining are sold domestically. If 8840 shirts remain for export, how many shirts were produced?', 'mcq', '13600', '13000', '13400', '14000', 'b', 'Non-defective = 0.85x; export = 80% of non-defective = 0.68x. Setting 0.68x = 8840 gives x = 13000.', NULL, 5, 'low', 'low', 90, 'Applying 20% and 15% directly to the total instead of layering the percentages sequentially.'),
  ('CAT2017_QA_S2_06', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'MIX_ALLIGATION', 'The average height of 22 toddlers increases by 2 inches when two of them (whose average height is one-third the original average) leave. Find the average height of the remaining 20.', 'mcq', '30', '28', '32', '26', 'c', 'Let the original average be 3x, so total = 66x and the two leaving toddlers average x. Remaining total = 64x over 20 toddlers giving average 3.2x; setting 3.2x-3x=2 gives x=10, so the answer is 32.', NULL, 6, 'medium', 'medium', 120, 'Assuming the two who leave have the overall average height rather than one-third of it.'),
  ('CAT2017_QA_S2_07', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'PL_CP_SP', 'A manufacturer sells a table to a wholesaler at 10% profit, who sells to a retailer at 30% profit, who sells to a customer at 50% profit for Rs 4290. Find the manufacturing cost.', 'mcq', '1500', '2000', '2500', '3000', 'b', 'Cost x satisfies 1.1×1.3×1.5×x = 4290, giving x = 2000.', NULL, 6, 'low', 'low', 90, 'Adding the percentages (10+30+50=90%) instead of multiplying the successive markup factors.'),
  ('CAT2017_QA_S2_08', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'PIPE_LEAK', 'An inlet pipe alone fills a tank in 8 hours; with the outlet open it takes 10 hours. If only the outlet is open, how long to empty half the tank?', 'mcq', '20', '30', '40', '45', 'a', 'Combined rate gives 1/8-1/x=1/10, so the outlet alone empties the tank in 40 hours; half the tank takes 20 hours.', NULL, 6, 'low', 'low', 90, 'Halving the full-tank draining time incorrectly or mixing up which pipe''s rate is being solved for.'),
  ('CAT2017_QA_S2_09', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'PL_CP_SP', 'Mayank buys equal dozens of two candy types at Rs 15 and Rs 12 per dozen, sells all at Rs 16.50 per dozen, making Rs 150 profit. How many dozens did he buy in total?', 'mcq', '50', '30', '25', '45', 'a', 'For x dozens of each type, cost = 27x, revenue = 33x, profit = 6x = 150 so x = 25; total dozens bought = 2x = 50.', NULL, 6, 'low', 'low', 90, 'Reporting x (25) instead of the total dozens (2x = 50) as the final answer.'),
  ('CAT2017_QA_S2_10', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'PERC_SUCCESSIVE', 'Food grain production rose 40% while per-capita production rose 27%. Find the nearest percentage increase in population.', 'mcq', '16', '13', '10', '7', 'c', 'Population ratio = 1.4/1.27 ≈ 1.10, so population increased by about 10%.', NULL, 6, 'low', 'low', 90, 'Subtracting the two percentages (40-27=13%) instead of dividing the growth factors.'),
  ('CAT2017_QA_S2_11', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'RATIO_BASIC', 'Positive integers a,b,c satisfy a:b=3:4 and b:c=2:1. Which of the following can be (a+b+c)?', 'mcq', '201', '205', '207', '210', 'c', 'Combining ratios gives a:b:c=3:4:2, so a+b+c=9x must be a multiple of 9; only 207 qualifies.', NULL, 5, 'low', 'low', 90, 'Combining the ratios incorrectly (not scaling b to a common value across both given ratios).'),
  ('CAT2017_QA_S2_12', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'TSD_RELATIVE', 'A motorbike leaves A at 1 pm for B; a car leaves B at 2 pm for A at double the bike''s speed. They meet at 3:40 pm, 168 km from A. Find the distance between A and B.', 'mcq', '364', '378', '380', '388', 'b', 'Bike travels for 2 hr 40 min and car for 1 hr 40 min. With car speed = 2×bike speed, solving x/(5/3)=2×168/(5/3) type relation gives car''s distance = 210 km, so AB = 210+168 = 378 km.', NULL, 7, 'high', 'medium', 150, 'Using the same travel duration for both vehicles despite their different start times.'),
  ('CAT2017_QA_S2_13', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'TW_WAGES', 'Amal (10 days) and Bimal (8 days) work with Kamal to finish a job in 4 days, earning Rs 1000 total, split by work done. Find Kamal''s share.', 'mcq', '100', '200', '300', '400', 'a', 'Kamal''s rate is 1/4-1/10-1/8=1/40, giving a work ratio of 4:5:1 among Amal:Bimal:Kamal, so Kamal earns 1/10×1000=Rs100.', NULL, 6, 'medium', 'medium', 120, 'Splitting the wage equally among three people instead of in proportion to individual work rates.'),
  ('CAT2017_QA_S2_14', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'MIX_ALLIGATION', 'Three water-liquid mixtures (water:A=1:2, water:B=1:3, water:C=1:4) are combined in ratio 4:3:2. Compare the resulting quantities of water, A, B, C.', 'mcq', 'Same water and liquid B', 'Same B and C', 'More water than B', 'More water than A', 'c', 'Computing each component''s contribution gives water=149/60, A=8/3, B=9/4, C=8/5; comparing these shows water exceeds liquid B.', NULL, 7, 'high', 'medium', 150, 'Comparing wrong pairs of components or forgetting each mixture''s own water fraction differs.'),
  ('CAT2017_QA_S2_15', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'GEO_POLY', 'ABCDEF is a regular hexagon with side 1 cm. Find the area of a square built on diagonal AC.', 'mcq', '3√2', '3', '4', '√3', 'b', 'In a regular hexagon of side s, the shorter diagonal AC = √3·s, so here AC=√3 and the square''s area is 3.', NULL, 6, 'medium', 'low', 90, 'Using the wrong hexagon diagonal formula (confusing AC with the long diagonal AD=2s).'),
  ('CAT2017_QA_S2_16', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'GEO_COMP', 'A pillar''s cross-section is a trapezium with parallel sides 10 cm and 20 cm, equal legs, and height (between parallel sides) 12 cm. If the pillar''s height is 20 cm, find the total surface area of all six faces.', 'mcq', '1300', '1340', '1480', '1520', 'c', 'The trapezium''s legs work out to 13 cm each (5-12-13 triangle), giving a base area of 180 each and a lateral area of perimeter×height = 56×20=1120; total = 1120+180+180=1480.', NULL, 7, 'high', 'medium', 150, 'Forgetting to include both top and bottom trapezium faces, or miscalculating the leg length.'),
  ('CAT2017_QA_S2_17', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'GEO_LINE', '(2,5) and (6,3) are endpoints of one diagonal of a rectangle. The other diagonal lies on y=3x+c. Find c.', 'mcq', '-5', '-6', '-7', '-8', 'd', 'Diagonals of a rectangle bisect each other, so the midpoint (4,4) lies on y=3x+c, giving c=-8.', NULL, 6, 'low', 'low', 90, 'Using an endpoint instead of the midpoint of the given diagonal to solve for c.'),
  ('CAT2017_QA_S2_18', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'GEO_CYCLIC', 'ABCD is cyclic with centre O inside it. If ∠COD=120° and ∠BAC=30°, find ∠BCD.', 'tita', NULL, NULL, NULL, NULL, '90', '∠CAD (angle subtended by chord CD at the circle) is half of ∠COD, so ∠CAD=60°; then ∠BAD=∠BAC+∠CAD=90°, and since opposite angles of a cyclic quadrilateral sum to 180°, ∠BCD=90°.', NULL, 6, 'medium', 'medium', 120, 'Forgetting the inscribed-angle theorem factor of 1/2 when relating ∠COD to ∠CAD.'),
  ('CAT2017_QA_S2_19', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'ALG_FUNC_OPT', 'Three sides of a rectangular park total 400 ft. Find the longer side length when the enclosed area is maximum.', 'tita', NULL, NULL, NULL, NULL, '200', 'With l+2b=400 (l the side without a matching pair), area = l(400-l)/2 is maximised using AM-GM at l=200, b=100.', NULL, 6, 'medium', 'medium', 120, 'Assuming all four sides sum to 400 rather than just three, changing the optimisation.'),
  ('CAT2017_QA_S2_20', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'GEO_TRI_CENTERS', 'P is an interior point of a right isosceles triangle ABC (hypotenuse AB) equidistant (distance 4(√2-1) cm) from all three sides. Find the area of ABC.', 'tita', NULL, NULL, NULL, NULL, '16', 'P is the incentre, so the given distance is the inradius r=(a+b-c)/2 for legs a=a and hypotenuse a√2; solving gives a=4√2, so area = a²/2 = 16.', NULL, 7, 'high', 'high', 150, 'Not recognising that equal distance from all three sides identifies the incentre and its inradius formula.'),
  ('CAT2017_QA_S2_21', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'NS_MISC', 'The product of three consecutive positive integers is 15600. Find the sum of the squares of these integers.', 'mcq', '1777', '1785', '1875', '1877', 'd', 'Writing the integers as x-1,x,x+1 gives x³-x=15600, and x=25 works (since 25³=15625); the integers are 24,25,26 with squares summing to 1877.', NULL, 6, 'medium', 'low', 90, 'Guessing integers close to the cube root of 15600 without verifying the exact product.'),
  ('CAT2017_QA_S2_22', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'ALG_LOG_EQ', 'If x is real and log_3(5) = log_5(2+x), which range must x lie in?', 'mcq', '0 < x < 3', '23 < x < 30', 'x > 30', '3 < x < 23', 'd', 'Since log_3(5) is between 1 and 2, log_5(2+x) is also between 1 and 2, so 5<2+x<25, giving 3<x<23.', NULL, 6, 'medium', 'medium', 90, 'Solving the log equation for an exact value of x rather than bounding log_3(5) between 1 and 2.'),
  ('CAT2017_QA_S2_23', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'ALG_FUNC_COMP', 'Let f(x)=x² and g(x)=2^x. Find f[f(g(x))+g(f(x))] at x=1.', 'mcq', '16', '18', '36', '40', 'c', 'g(1)=2, f(2)=4; f(1)=1, g(1)=2; sum=4+2=6, so f(6)=36.', NULL, 5, 'low', 'low', 90, 'Mixing up the order of composition, e.g. computing g(f(x)) as f(g(x)).'),
  ('CAT2017_QA_S2_24', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'ALG_QUAD_ROOT', 'Find the minimum possible value of the sum of squares of the roots of x²+(a+3)x-(a+5)=0.', 'mcq', '1', '2', '3', '4', 'c', 'With roots p,q: p+q=-(a+3), pq=-(a+5), so p²+q²=(a+4)²+3, minimised at a=-4 giving 3.', NULL, 7, 'medium', 'medium', 120, 'Forgetting p²+q²=(p+q)²-2pq and instead trying to minimise p+q or pq directly.'),
  ('CAT2017_QA_S2_25', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'ALG_EXP', 'Solve for x: 9^(x-1/2) - 2^(2x-2) = 4^x - 3^(2x-3).', 'mcq', '3/2', '2/5', '3/4', '4/9', 'a', 'Rearranging into 3^(2x-1)+3^(2x-3)=2^(2x)+2^(2x-2) and simplifying leads to 3^(2x-3)=2^(2x-3), which forces 2x-3=0, so x=3/2.', NULL, 8, 'high', 'high', 150, 'Trying to isolate x by taking logs directly instead of first grouping same-base terms.'),
  ('CAT2017_QA_S2_26', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'ALG_LOG', 'log(2^a×3^b×5^c) is the arithmetic mean of log(2²×3³×5), log(2⁶×3×5⁷) and log(2×3²×5⁴). Find a.', 'tita', NULL, NULL, NULL, NULL, '3', 'Averaging the exponents of 2 across the three terms gives (2+6+1)/3=3, so a=3.', NULL, 7, 'medium', 'medium', 120, 'Averaging the full logarithmic values instead of averaging each prime''s exponent separately.'),
  ('CAT2017_QA_S2_27', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'ALG_AP', 'a1..a5 are five consecutive odd numbers. A new sequence of five consecutive even numbers ends with 2a3. If the new sequence sums to 450, find a5.', 'tita', NULL, NULL, NULL, NULL, '51', 'The five consecutive even numbers ending at 2a3 sum to 10a3-20=450, giving a3=47; since the odd numbers are consecutive, a5=a3+4=51.', NULL, 6, 'medium', 'medium', 120, 'Confusing which term of the odd sequence (a3) anchors the even sequence''s last term.'),
  ('CAT2017_QA_S2_28', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'NS_FACTORS', 'How many pairs (a,b) of positive integers with a≥b satisfy 1/a + 1/b = 1/9?', 'tita', NULL, NULL, NULL, NULL, '3', 'Rearranging gives (a-9)(b-9)=81; factor pairs of 81 with a≥b give (90,10),(36,12),(18,18), i.e. 3 pairs.', NULL, 7, 'medium', 'medium', 150, 'Missing the algebraic trick of adding 81 to both sides to factor the expression.'),
  ('CAT2017_QA_S2_29', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'MOD_DISTRIBUTION', 'In how many ways can 8 identical pens be distributed among Amal, Bimal, Kamal with Amal getting at least 1, Bimal at least 2, Kamal at least 3?', 'tita', NULL, NULL, NULL, NULL, '6', 'After giving the minimum (1+2+3=6) pens, 2 pens remain to distribute freely among 3 people: (2+3-1)C(3-1) = 4C2 = 6.', NULL, 6, 'medium', 'medium', 90, 'Forgetting to subtract the minimum allocation before applying the stars-and-bars formula.'),
  ('CAT2017_QA_S2_30', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'MOD_ADVANCED', 'How many four-digit numbers divisible by 6, using digits 0,2,3,4,6 without repetition and no leading zero, can be formed?', 'tita', NULL, NULL, NULL, NULL, '50', 'Splitting into cases by which four digits are chosen (sum divisible by 3) and counting valid even-ending, non-zero-leading arrangements in each case gives 18+14+18=50.', NULL, 7, 'high', 'high', 150, 'Forgetting the units digit must be even (for divisibility by 2) alongside the digit-sum rule for 3.'),
  ('CAT2017_QA_S2_31', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'ALG_SPECIAL', 'If f(ab)=f(a)f(b) for all positive integers a,b, find the largest possible value of f(1).', 'tita', NULL, NULL, NULL, NULL, '1', 'Setting a=b=1 gives f(1)=f(1)², so f(1)=0 or 1; the largest possible value is 1.', NULL, 6, 'low', 'low', 60, 'Assuming f(1) must be positive and skipping the check that f(1)=f(1)² has two roots.'),
  ('CAT2017_QA_S2_32', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'ALG_INEQ_MOD', 'Let f(x)=2x-5 and g(x)=7-2x. For what x does |f(x)+g(x)|=|f(x)|+|g(x)|?', 'mcq', '5/2 < x < 7/2', 'x≤5/2 or x≥7/2', 'x<5/2 or x≥7/2', '5/2 ≤ x ≤ 7/2', 'd', 'The identity holds when f(x) and g(x) have the same sign (or are zero); solving both ≥0 and both ≤0 simultaneously gives 5/2≤x≤7/2.', NULL, 6, 'medium', 'medium', 120, 'Only checking one of the two sign cases (both non-negative) and missing the both-non-positive case.'),
  ('CAT2017_QA_S2_33', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'ALG_GP', 'An infinite GP a1,a2,... satisfies an=3(a_(n+1)+a_(n+2)+...) for every n≥1. If the sum to infinity is 32, find a5.', 'mcq', '1/32', '2/32', '3/32', '4/32', 'c', 'The condition gives common ratio r=1/4; from a1/(1-r)=32, a1=24, so a5=24×(1/4)^4=3/32.', NULL, 7, 'high', 'high', 150, 'Misinterpreting the recursive sum condition as a simple recurrence rather than deriving the common ratio.'),
  ('CAT2017_QA_S2_34', 2017, 'Slot 2', 'CAT 2017 Slot 2 Official', TRUE, 'ALG_SERIES_SPECIAL', 'If a1=1/(2×5), a2=1/(5×8), a3=1/(8×11), ..., find a1+a2+...+a100.', 'mcq', '25/151', '1/2', '1/4', '111/55', 'a', 'Each term telescopes as (1/3)(1/(3n-1) - 1/(3n+2)); summing to n=100 collapses to (1/3)(1/2-1/302)=25/151.', NULL, 7, 'medium', 'medium', 150, 'Not recognising the telescoping pattern and attempting to sum each fraction individually.'),
  ('CAT2017_QA_S1_01', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'ALG_LINEAR_WORD', 'Arun''s present age is 40% of Barun''s. In a few years, Arun''s age will be half of Barun''s. By what percentage will Barun''s age increase during this period?', 'tita', NULL, NULL, NULL, NULL, '20', 'With Arun=0.4B initially, after k years 2(0.4B+k)=B+k gives k=0.5B, so Barun''s age rises by 0.5B/2.5B=20%.', NULL, 6, 'low', 'medium', 90, 'Setting up the ''half of Barun''s age'' condition using the original ages instead of the ages after k years.'),
  ('CAT2017_QA_S1_02', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'TW_COMBINED', 'One person alone completes a job in 120 days. Each following day one more person of equal efficiency joins (1 on day 1, 2 on day 2, etc). How many days to finish?', 'tita', NULL, NULL, NULL, NULL, '15', 'Total work=120x (x = one person''s daily rate); work done after n days is x·n(n+1)/2, so n(n+1)=240 gives n=15.', NULL, 7, 'medium', 'medium', 120, 'Treating the daily contribution as constant instead of increasing by one worker each day.'),
  ('CAT2017_QA_S1_03', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'NS_MISC', 'A lift has a 630 kg limit; the heaviest person weighs 57 kg and the lightest 53 kg. What is the maximum possible number of people in the group?', 'tita', NULL, NULL, NULL, NULL, '11', 'To maximise headcount, all but the two extremes weigh the minimum (53 kg): 53+53n+57≤630 gives n≤9.8, so 9+2=11 people.', NULL, 5, 'low', 'medium', 90, 'Forgetting to keep exactly one heaviest and one lightest person and instead using only the minimum weight throughout.'),
  ('CAT2017_QA_S1_04', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'TSD_BASIC', 'Walking at 12 km/h a man reaches the station 10 min after the train departs; at 15 km/h he arrives 10 min before. Find the distance to the station.', 'tita', NULL, NULL, NULL, NULL, '20', 'The 20-minute (1/3 hr) time saving gives d/12 - d/15 = 1/3, so d=20 km.', NULL, 6, 'low', 'low', 90, 'Setting the time difference as 10 minutes instead of the full 20-minute swing between the two scenarios.'),
  ('CAT2017_QA_S1_05', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'PERC_SUCCESSIVE', 'Ravi puts 50% of savings in FDs, 30% of the remainder in stocks, and the rest in his savings account. If FD+savings account total Rs 59500, find his total savings.', 'tita', NULL, NULL, NULL, NULL, '70000', 'FD=50%, savings account=35% of total, so 85% of savings=59500, giving total savings=Rs 70000.', NULL, 5, 'low', 'low', 90, 'Adding only the savings-account percentage (35%) and forgetting to include the FD share in the 59500 total.'),
  ('CAT2017_QA_S1_06', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'PL_DISCOUNT', 'A 15% discount on retail price still gives 2% profit. Which option guarantees 20% profit?', 'mcq', 'Give a discount of 5% on retail price.', 'Give a discount of 2% on retail price.', 'Increase the retail price by 2%.', 'Sell at retail price.', 'd', '0.85×Marked=1.02×Cost gives Marked=1.2×Cost, so selling at the marked (retail) price directly yields 20% profit.', NULL, 6, 'medium', 'medium', 90, 'Assuming a further discount could still yield higher profit instead of realising retail price already equals 1.2×cost.'),
  ('CAT2017_QA_S1_07', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'TSD_BOAT', 'A man''s downriver round trip time drops by 75% if he doubles his boat speed (river speed unchanged). Find the ratio of original boat speed to river speed.', 'mcq', '√6:√2', '√7:2', '2√5:3', '3:2', 'b', 'Equating the original round-trip time to 1/4 of itself using the doubled-speed formula leads to u²/x²=7/4, so u:x=√7:2.', NULL, 7, 'high', 'high', 150, 'Applying the average-speed shortcut for up-down trips incorrectly instead of summing individual leg times.'),
  ('CAT2017_QA_S1_08', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'RATIO_BASIC', 'C1:C2:C3=9:10:8 and C2:C4:C5=18:19:20 in profits. If C5 exceeds C1 by Rs 19 crore, find total profit of all five companies.', 'mcq', '438 crore', '435 crore', '348 crore', '345 crore', 'a', 'Scaling both ratios to a common C2 gives C1:C2:C3:C4:C5=81:90:72:95:100; since 100x-81x=19 gives x=1, total=438 crore.', NULL, 7, 'medium', 'medium', 120, 'Combining the two given ratios without first scaling C2 to a common value in both.'),
  ('CAT2017_QA_S1_09', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'PERC_BASIC', 'Girls appearing are twice the boys. 30% of girls and 45% of boys get admission. What percentage of candidates do not get admission?', 'mcq', '35', '50', '60', '65', 'd', 'With boys=x, girls=2x: admitted=0.45x+0.6x=1.05x out of 3x, so not admitted=1.95x/3x=65%.', NULL, 5, 'low', 'low', 90, 'Averaging the two admission percentages directly instead of weighting by the 1:2 boys-to-girls ratio.'),
  ('CAT2017_QA_S1_10', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'RATIO_BASIC', 'Popcorn packets (L:S:J)=7:17:16 and chips packets=6:15:14. Total popcorn packets equal total chips packets. Find the ratio of jumbo popcorn to jumbo chips packets.', 'mcq', '1:1', '8:7', '4:3', '6:5', 'a', 'Setting 40x=35y gives x=7y/8; jumbo popcorn=16x=14y, matching jumbo chips=14y exactly, so the ratio is 1:1.', NULL, 6, 'medium', 'medium', 120, 'Comparing jumbo counts directly without first equating the total packet counts across both product lines.'),
  ('CAT2017_QA_S1_11', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'MIX_ALLIGATION', 'Medium mango price is half of good mango price. A shopkeeper buys 80 kg good and 40 kg medium mangoes, sells all at 10% below the good-mango buying price. Find his overall profit %.', 'mcq', '6%', '8%', '10%', '12%', 'b', 'With good mango at 2x/kg: cost=200x, selling price=1.8x for all 120 kg giving revenue=216x, so profit=16x/200x=8%.', NULL, 6, 'medium', 'medium', 120, 'Computing profit only on the good mangoes and ignoring the loss/gain on the medium-quality batch.'),
  ('CAT2017_QA_S1_12', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'PL_DISCOUNT', 'Selling 60 toys at 40% discount on marked price gives 20% profit. If 10 toys are destroyed and the rest sold, what discount keeps the same total profit?', 'mcq', '30%', '25%', '24%', '28%', 'd', 'Marked price M=2×cost C (from 0.6M=1.2C); for the total profit on 60 toys to be earned from only 50, M(1-d)×50=1.2×60C gives d=0.28.', NULL, 7, 'high', 'high', 120, 'Recomputing profit percentage per toy instead of preserving the original total rupee profit target.'),
  ('CAT2017_QA_S1_13', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'ALG_BASIC', 'Integers a,b of opposite sign satisfy (a+3)²:b²=9:1 and (a-1)²:(b-1)²=4:1. Find a²:b².', 'mcq', '9:4', '81:4', '1:4', '25:4', 'd', 'Taking square roots with sign choices and solving the resulting linear systems, the valid opposite-sign solution is a=15, b=-6, giving a²:b²=25:4.', NULL, 7, 'high', 'high', 150, 'Missing that square-root equations yield ± cases and only solving one combination instead of checking all four.'),
  ('CAT2017_QA_S1_14', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'MIX_ALLIGATION', 'A class has 20 boys, 30 girls. Girls'' mid-sem average was 5 higher than boys''. In finals, girls'' average dropped by 3 while the class average rose by 2. Find the boys'' average increase.', 'mcq', '9.5', '10', '4.5', '6', 'a', 'Tracking total scores through mid-sem and final averages algebraically shows the boys'' average rose by 9.5.', NULL, 7, 'high', 'high', 150, 'Assuming the class-average change splits evenly between boys and girls instead of weighting by group size.'),
  ('CAT2017_QA_S1_15', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'GEO_LOCUS', 'Find the area enclosed by |x|+|y|=2.', 'mcq', '4π sq units', '4 sq units', '8 sq units', '2π sq units', 'c', 'The equation traces a square (rotated) with diagonals of length 4 along each axis, giving area = (1/2)×4×4=8.', NULL, 6, 'medium', 'medium', 90, 'Mistaking the diamond shape for a circle and using a circular-area formula.'),
  ('CAT2017_QA_S1_16', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'GEO_TRI_CENTERS', 'Triangle ABC has sides 40, 25, 35 ft. A triangular portion GBC (G the centroid) is removed. Find the remaining area.', 'mcq', '225√3', '500/√3', '275/√3', '250/√3', 'b', 'Area of ABC (Heron''s formula) = 250√3; since the centroid divides each median 2:1, triangle GBC is 1/3 of ABC''s area, leaving 2/3×250√3=500/√3.', NULL, 7, 'high', 'high', 150, 'Forgetting the centroid-to-vertex median ratio and instead assuming GBC is half of ABC.'),
  ('CAT2017_QA_S1_17', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'GEO_SECTOR', 'Right isosceles triangle ABC (legs AB=AC=6, hypotenuse BC) has semicircle BQC on BC and arc BPC centred at A between BC and BQC. Find the area enclosed by BPC and BQC.', 'mcq', '9π-18', '18', '9π', '9', 'b', 'BC=6√2; area of semicircle BQC = 9π and the quadrant BPC (radius 6, centred at A) also has area 9π, so the region equals the triangle''s area, 18.', NULL, 7, 'high', 'high', 120, 'Not noticing the two circular areas (semicircle and quadrant) are equal and cancel, leaving just the triangle''s area.'),
  ('CAT2017_QA_S1_18', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'GEO_CUBE', 'A cube is melted into 5 smaller cubes with volume ratio 1:1:8:27:27. By what percentage does the sum of their surface areas exceed the original cube''s surface area?', 'mcq', '10', '50', '60', '20', 'b', 'Side lengths are a,a,2a,3a,3a summing (cubed) to (4a)³; comparing 6(a²+a²+4a²+9a²+9a²)=144a² to the original 96a² gives a 50% increase.', NULL, 7, 'high', 'high', 150, 'Comparing volumes instead of converting each smaller cube''s volume ratio into its corresponding side length first.'),
  ('CAT2017_QA_S1_19', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'GEO_COMP', 'A ball of diameter 4 cm sits on top of a hollow cylinder of height 3 cm and volume 9π cubic cm. Find the vertical distance from the base of the cylinder to the top of the ball.', 'tita', NULL, NULL, NULL, NULL, '6', 'Cylinder radius √3 cm and ball radius 2 cm give a vertical offset of 1 cm (Pythagoras) between the cylinder rim and ball centre, so total height = 3+1+2=6 cm.', NULL, 6, 'high', 'high', 120, 'Assuming the ball''s centre sits directly above the cylinder rim without accounting for the radius mismatch.'),
  ('CAT2017_QA_S1_20', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'GEO_TRIG_BPH', 'Right triangle ABC has AB=15 km, AC=20 km (right angle at A). Find the minimum time (minutes) to reach hypotenuse BC from A at 30 km/h.', 'tita', NULL, NULL, NULL, NULL, '24', 'Hypotenuse BC=25 km; the shortest path is the altitude from A, length (15×20)/25=12 km, taking 12/30 hr = 24 minutes.', NULL, 6, 'medium', 'medium', 90, 'Using one of the legs as the shortest distance instead of computing the perpendicular altitude to the hypotenuse.'),
  ('CAT2017_QA_S1_21', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'ALG_LOG', 'log_3(x)=log_12(y)=a for positive x,y. If G is the geometric mean of x and y, find log_6(G).', 'mcq', '√a', '2a', 'a/2', 'a', 'd', 'x=3^a, y=12^a, so G=√(xy)=√(36^a)=6^a, giving log_6(G)=a.', NULL, 6, 'low', 'low', 120, 'Forgetting that √(3^a×12^a)=√(36^a)=6^a simplifies neatly, and instead trying separate log manipulations.'),
  ('CAT2017_QA_S1_22', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'ALG_HIGHER_DEGREE', 'If x+1=x² and x>0, find 2x⁴.', 'mcq', '6+4√5', '3+3√5', '5+3√5', '7+3√5', 'd', 'x⁴=(x+1)²=3x+2 using x²=x+1 twice; with x=(1+√5)/2, 2x⁴=6x+4=3√5+7.', NULL, 7, 'medium', 'medium', 120, 'Substituting x''s numeric value too early instead of first reducing x⁴ algebraically in terms of x.'),
  ('CAT2017_QA_S1_23', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'ALG_LOG', 'Evaluate log_0.008(√5) + log_√3(81) - 7.', 'mcq', '1/3', '2/3', '5/6', '7/6', 'c', '0.008=5^-3 and 81=3^4, so the expression becomes (1/2)/(-3) + 8 - 7 = -1/6+1 = 5/6.', NULL, 6, 'medium', 'medium', 120, 'Misconverting 0.008 to a power of 5 or mishandling the square-root exponent in log_0.008(√5).'),
  ('CAT2017_QA_S1_24', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'ALG_EXP', 'If 9^(2x-1) - 81^(x-1) = 1944, find x.', 'mcq', '3', '9/4', '4/9', '1/3', 'b', 'Put both terms over base 81^x: 9^(2x−1) = 81^x/9 and 81^(x−1) = 81^x/81. The equation becomes 81^x(1/9 − 1/81) = 81^x × 8/81 = 1944, so 81^x = 1944 × 81/8 = 243 × 81 = 19683 = 3^9. Since 81^x = 3^(4x), we need 4x = 9, giving x = 9/4.', NULL, 7, 'high', 'high', 120, 'Errors converting 9^(2x-1) and 81^(x-1) to a common base before factoring.'),
  ('CAT2017_QA_S1_25', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'MOD_ADVANCED', 'Positive integers x,y,z satisfy x-y-z=25 with x≤40, y≤12, z≤12. How many solutions (x,y,z) exist?', 'mcq', '101', '99', '87', '105', 'b', 'For each value of x from 40 down, y+z is fixed and the count of valid (y,z) pairs (each ≤12) is computed and summed, totalling 99.', NULL, 8, 'high', 'high', 150, 'Not capping y,z at 12 correctly for each x, leading to over- or under-counting valid pairs.'),
  ('CAT2017_QA_S1_26', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'ALG_INEQ_QUAD', 'For how many integers n does (n-5)(n-10)-3(n-2)≤0 hold?', 'tita', NULL, NULL, NULL, NULL, '11', 'Expanding gives n²-18n+56≤0, i.e. (n-4)(n-14)≤0, so n ranges from 4 to 14 inclusive — 11 integers.', NULL, 5, 'low', 'low', 90, 'Forgetting to include both endpoints of the inequality when counting integer solutions.'),
  ('CAT2017_QA_S1_27', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'ALG_QUAD_ROOT', 'f1(x)=x²+11x+n and f2(x)=x. Find the largest positive integer n for which f1(x)=f2(x) has two distinct real roots.', 'tita', NULL, NULL, NULL, NULL, '24', 'f1(x)=f2(x) gives x²+10x+n=0; for two distinct real roots, discriminant 100-4n>0, so n<25, making the largest integer n=24.', NULL, 6, 'low', 'low', 90, 'Using ≥0 instead of strictly >0 for the discriminant, which would wrongly allow n=25.'),
  ('CAT2017_QA_S1_28', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'ALG_FUNC_OPT', 'Integers a,b,c,d satisfy a+b+c+d=30. Find the minimum possible value of (a-b)²+(a-c)²+(a-d)².', 'tita', NULL, NULL, NULL, NULL, '2', 'The expression is minimised when a,b,c,d are as close as possible; with sum 30 the closest integer split is 8,8,7,7, giving (0)²+(1)²+(1)²=2.', NULL, 7, 'medium', 'medium', 120, 'Trying non-integer or unequal splits instead of the closest possible integer partition of 30 into 4 parts.'),
  ('CAT2017_QA_S1_29', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'MOD_SELECT', 'AB, CD, EF, GH, JK are five diameters of a circle centred at O. In how many ways can 3 points be chosen from the 11 labelled points (10 on the circle plus O) to form a triangle?', 'tita', NULL, NULL, NULL, NULL, '160', 'Total selections = 11C3 = 165; subtracting the 5 collinear triples (each diameter with O) gives 165-5=160.', NULL, 6, 'medium', 'medium', 120, 'Forgetting to exclude the collinear triples formed by each diameter passing through the centre O.'),
  ('CAT2017_QA_S1_30', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'ALG_INEQ_MOD', 'Find the shortest distance of the point (1/2, 1) from the curve y = |x-1| + |x+1|.', 'mcq', '1', '0', '√2', '√(3/2)', 'a', 'For -1≤x≤1 the curve is the constant y=2; the vertical distance from (1/2,1) to this segment is 1, which is the minimum over the whole curve.', NULL, 7, 'medium', 'medium', 120, 'Trying to minimise distance using the outer sloped branches of the curve instead of checking the flat middle segment first.'),
  ('CAT2017_QA_S1_31', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'ALG_AP', 'In an AP with positive common difference, the square of the 7th term equals the product of the 3rd and 17th terms. Find the ratio of the first term to the common difference.', 'mcq', '2:3', '3:2', '3:4', '4:3', 'a', '(a+6d)²=(a+2d)(a+16d) simplifies to 4d²=6ad, giving d:a=3:2, so a:d=2:3.', NULL, 6, 'medium', 'medium', 120, 'Solving for d:a but reporting it as a:d without inverting the ratio.'),
  ('CAT2017_QA_S1_32', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'MOD_DISTRIBUTION', 'In how many ways can 7 identical erasers be distributed among 4 kids so each gets at least 1 but no more than 3?', 'mcq', '16', '20', '14', '15', 'a', 'Using stars-and-bars for a+b+c+d=7 with each 1≤var≤3 (shift to 0≤var''≤2, sum=3): total unrestricted ways minus those violating the upper cap works out to 16.', NULL, 6, 'high', 'high', 150, 'Applying plain stars-and-bars without adjusting for the upper cap of 3 erasers per kid.'),
  ('CAT2017_QA_S1_33', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'ALG_FUNC_COMP', 'f(x)=(5x+2)/(3x-5), g(x)=x²-2x-1. Find g(f(f(3))).', 'mcq', '2', '1/3', '6', '2/3', 'a', 'f(3)=17/4, f(17/4)=93/31=3, then g(3)=9-6-1=2.', NULL, 6, 'medium', 'medium', 120, 'Arithmetic slips while simplifying the nested rational function f(f(3)).'),
  ('CAT2017_QA_S1_34', 2017, 'Slot 1', 'CAT 2017 Slot 1 Official', TRUE, 'ALG_AP', 'AP a1,a2,...,a3n has a1=3, a2=7. If a1+a2+...+a3n=1830, find the smallest positive integer m such that m(a1+a2+...+an) > 1830.', 'mcq', '8', '9', '10', '11', 'b', 'Common difference=4; solving 1830=(3n/2)(6+4(3n-1)) gives 3n=30 so n=10; sum of first 10 terms=210, and 210m>1830 needs m≥9.', NULL, 7, 'high', 'high', 150, 'Solving for 3n but then using the wrong term count (3n instead of n) when computing the first-n-terms sum.'),
  ('CAT2018_QA_S2_01', 2018, 'Slot 2', 'CAT 2018 Slot 2 Official', TRUE, 'PIPE_FILL', '10 type-A and 45 type-B inlets fill a tank in 30 min; 8 type-A and 18 type-B inlets fill it in 60 min. How many minutes for 7 type-A and 27 type-B inlets?', 'tita', NULL, NULL, NULL, NULL, '48', 'Equating (10a+45b)/2=(8a+18b) gives 6a=9b; tank capacity=20a. With 7a+27b=25a, time=20a/25a×60=48 minutes.', NULL, 6, 'high', 'medium', 120, 'Not converting the two given fill times to the same units before equating tank capacities.'),
  ('CAT2018_QA_S2_02', 2018, 'Slot 2', 'CAT 2018 Slot 2 Official', TRUE, 'ALG_FUNC_OPT', 'For x>0, let f(x)=max(5x, 52-2x²). Find the minimum possible value of f(x).', 'tita', NULL, NULL, NULL, NULL, '20', 'The minimum of the max occurs where the two expressions are equal: 5x=52-2x² gives x=4 (rejecting the negative root), so f(x)=20.', NULL, 7, 'medium', 'medium', 120, 'Minimising each branch separately instead of finding the crossover point of the two expressions.'),
  ('CAT2018_QA_S2_03', 2018, 'Slot 2', 'CAT 2018 Slot 2 Official', TRUE, 'TSD_RELATIVE', 'A,P,Q,B are collinear with P,Q,B at 100,200,300 km from A. Cars 1,2 leave A together toward B; Car 3 leaves B toward A at the same time, meeting Car1 at Q and Car2 at P. Find speed(Car2):speed(Car1).', 'mcq', '2:7', '2:9', '1:2', '1:4', 'd', 'Car1 & Car3 meet at Q (200 km from A, 100 from B) and Car2 & Car3 meet at P (100 from A, 200 from B); using the shared time-to-meet for Car3 in both cases gives speed ratio Car1:Car2:Car3=4:1:2, so Car2:Car1=1:4.', NULL, 7, 'high', 'high', 150, 'Assuming Car3 meets both other cars at the same time, ignoring that the two meetings happen at different times.'),
  ('CAT2018_QA_S2_04', 2018, 'Slot 2', 'CAT 2018 Slot 2 Official', TRUE, 'ALG_HIGHER_DEGREE', 'Find the smallest integer n such that n³-11n²+32n-28 > 0.', 'tita', NULL, NULL, NULL, NULL, '8', 'Factoring gives (n-2)²(n-7), which is positive exactly when n>7 (since the squared term is always ≥0), so the smallest integer is n=8.', NULL, 7, 'medium', 'medium', 120, 'Not recognising the repeated root at n=2 and mistakenly including values just above n=2 as solutions.'),
  ('CAT2018_QA_S2_05', 2018, 'Slot 2', 'CAT 2018 Slot 2 Official', TRUE, 'RATIO_BASIC', 'Amal:Bimal scores are 11:14. After equal-point increases, the new ratio is 47:56. Find Bimal''s new score : his original score.', 'mcq', '4:3', '8:5', '5:4', '3:2', 'a', 'Setting scores 11k,14k and increase x, (11k+x)/(14k+x)=47/56 gives x=42k/9; Bimal''s new-to-original ratio simplifies to 4:3.', NULL, 6, 'medium', 'medium', 120, 'Solving for the increase x but then computing the wrong ratio (using Amal''s scores instead of Bimal''s).'),
  ('CAT2018_QA_S2_06', 2018, 'Slot 2', 'CAT 2018 Slot 2 Official', TRUE, 'NS_MISC', 'How many two-digit numbers with a non-zero units digit are more than thrice the number formed by reversing their digits?', 'tita', NULL, NULL, NULL, NULL, '6', 'With digits a (tens), b (units), the condition 10a+b>3(10b+a) simplifies to 7a>29b; checking b=1,2,3 gives 6 valid numbers total.', NULL, 6, 'medium', 'medium', 120, 'Forgetting the non-zero-units-digit condition and including numbers ending in 0.'),
  ('CAT2018_QA_S2_07', 2018, 'Slot 2', 'CAT 2018 Slot 2 Official', TRUE, 'SET_OPERATIONS', 'For sets P={1,2,3,4}, Q={2,3,5,6}, R={1,3,7,8,9}, S={2,4,9,10}, find the number of elements in (PΔQ)Δ(RΔS), where Δ is symmetric difference.', 'tita', NULL, NULL, NULL, NULL, '7', 'PΔQ keeps what is in exactly one of P, Q: {1, 4, 5, 6} (2 and 3 are dropped as common). RΔS keeps {1, 3, 7, 8} from R and {2, 4, 10} from S, dropping the shared 9: RΔS = {1, 2, 3, 4, 7, 8, 10}. Their symmetric difference drops the shared elements 1 and 4, leaving {5, 6} from the first set and {2, 3, 7, 8, 10} from the second — 7 elements in all.', NULL, 6, 'medium', 'medium', 120, 'Computing the union or intersection instead of the symmetric difference at either stage.'),
  ('CAT2018_QA_S2_08', 2018, 'Slot 2', 'CAT 2018 Slot 2 Official', TRUE, 'GEO_QUAD', 'Parallelogram ABCD has area 48 sq cm, CD=8 cm, AD=s cm. Which must be true about s?', 'mcq', 's≠6', 's≥6', '5≤s≤7', 's≤6', 'b', 'Area=CD×AD×sin(angle)=48 with sin(angle)≤1 forces AD≥6, so s≥6.', NULL, 6, 'medium', 'medium', 90, 'Treating the parallelogram as if AD were automatically the height, missing the sine-of-angle factor.'),
  ('CAT2018_QA_S2_09', 2018, 'Slot 2', 'CAT 2018 Slot 2 Official', TRUE, 'MIX_ALLIGATION', 'A 20% ethanol solution is mixed with unknown-strength solution S in ratio 1:3, then mixed with an equal volume of 20% solution, giving a final 31.25% mixture. Find S''s concentration.', 'mcq', '30%', '40%', '50%', '60%', 'c', 'For 100 ml of 20% + 300 ml of S mixed with 400 ml more 20% solution (800 ml total) at 31.25%, solving 20+300S+80=250 gives S=50%.', NULL, 6, 'medium', 'medium', 120, 'Losing track of the total volume after the second mixing step.'),
  ('CAT2018_QA_S2_10', 2018, 'Slot 2', 'CAT 2018 Slot 2 Official', TRUE, 'MOD_SELECT', '43 juniors and 51 seniors each play round-robin within their level (no cross-level matches). Junior girl-vs-girl matches = 153, senior boy-vs-boy matches = 276. Find the number of boy-vs-girl matches.', 'tita', NULL, NULL, NULL, NULL, '1098', '153=gC2 gives 18 junior girls (so 25 junior boys); 276=bC2 gives 24 senior boys (so 27 senior girls); total mixed matches=18×25+24×27=1098.', NULL, 7, 'high', 'high', 150, 'Applying the boy-vs-girl formula within the wrong level or mixing junior and senior counts.'),
  ('CAT2018_QA_S2_11', 2018, 'Slot 2', 'CAT 2018 Slot 2 Official', TRUE, 'GEO_CIRCLE_CHORD', 'A chord of length 5 cm subtends 60° at the centre. Find the length of a chord subtending 120° in the same circle.', 'mcq', '5√3', '2π', '8', '6√2', 'a', 'The 60° chord equals the radius (5 cm, equilateral triangle); for the 120° chord, splitting into two right triangles gives length 5√3 cm.', NULL, 6, 'medium', 'medium', 120, 'Assuming chord length scales linearly with the subtended angle, which it does not.'),
  ('CAT2018_QA_S2_12', 2018, 'Slot 2', 'CAT 2018 Slot 2 Official', TRUE, 'ALG_AP', 'Positive integers a1<a2<...<a52 have a mean one less than the mean of a2,...,a52. If a52=100, find the largest possible a1.', 'mcq', '48', '20', '23', '45', 'c', 'Setting a1=x-51 where x is the mean of all 52 terms, and maximising x by making a2..a52 the tightest possible run of consecutive integers ending at 100 gives x=74, so a1=23.', NULL, 7, 'high', 'high', 150, 'Not realising a2..a51 should be as large (tightly packed near 100) as possible to maximise a1.'),
  ('CAT2018_QA_S2_13', 2018, 'Slot 2', 'CAT 2018 Slot 2 Official', TRUE, 'ALG_SERIES_SPECIAL', 'Find the value of the sum 7×11 + 11×15 + 15×19 + ... + 95×99.', 'tita', NULL, NULL, NULL, NULL, '80707', 'The nth term is (4n+3)(4n+7); summing this quadratic expression for n=1 to 23 (since 4n+3=95 gives n=23) totals 80707.', NULL, 7, 'medium', 'medium', 150, 'Miscounting the number of terms n (should stop at n=23, not 24 or 25) in the summation.'),
  ('CAT2018_QA_S2_14', 2018, 'Slot 2', 'CAT 2018 Slot 2 Official', TRUE, 'NS_FACTORS', 'N,x are positive integers with N^N=2^160, and N²+2^N is an integral multiple of 2^x. Find the largest possible x.', 'tita', NULL, NULL, NULL, NULL, '10', 'N^N=2^160 gives N=32; N²+2^N=2^10+2^32=2^10(1+2^22), so the highest power of 2 dividing it is 2^10, giving x=10.', NULL, 7, 'high', 'high', 150, 'Trying to factor 2^10+2^32 without pulling out the common power of 2 first.'),
  ('CAT2018_QA_S2_15', 2018, 'Slot 2', 'CAT 2018 Slot 2 Official', TRUE, 'PIPE_FILL', 'A tank is emptied daily at a fixed time. Pump A alone finished at 8pm Monday, pump B alone at 6pm Tuesday, and A till 5pm then B till 7pm on Wednesday. What time is it filled Thursday if both pumps run together?', 'mcq', '4:48 pm', '4:12 pm', '4:24 pm', '4:36 pm', 'c', 'Setting up equations for the unknown empty-time t using each day''s scenario gives t=2pm, with A taking 6 hrs and B taking 4 hrs alone; combined rate fills in 2.4 hrs, so the tank fills by 4:24 pm.', NULL, 8, 'high', 'high', 180, 'Not first solving for the (unknown) daily emptying time before computing each pump''s individual fill duration.'),
  ('CAT2018_QA_S2_16', 2018, 'Slot 2', 'CAT 2018 Slot 2 Official', TRUE, 'ALG_BASIC', 'Mean of x,y,z is 80; mean of x,y,z,u,v is 75, where u=(x+y)/2, v=(y+z)/2. If x≥z, find the minimum possible value of x.', 'tita', NULL, NULL, NULL, NULL, '105', 'x+y+z=240 and u+v=135 leads to y=30, so x+z=210; since x≥z, the minimum x is when x=z=105.', NULL, 7, 'high', 'high', 150, 'Forgetting the x≥z constraint and instead trying to minimise x without that lower bound.'),
  ('CAT2018_QA_S2_17', 2018, 'Slot 2', 'CAT 2018 Slot 2 Official', TRUE, 'TSD_BASIC', 'A and B (150 km apart) are covered by two cars leaving A, car2 starting once car1 is 20 km ahead. Both cars travel 50km segments at 100, 50, 25 km/h respectively. Find the distance between car2 and B when car1 reaches B.', 'tita', NULL, NULL, NULL, NULL, '5', 'Car1 reaches B in a total 3.5 hr; accounting for the head-start gap, car2 has been travelling 3 hr 18 min when car1 finishes, covering 145 km, leaving it 5 km short of B.', NULL, 7, 'high', 'high', 150, 'Not properly accounting for the time offset caused by car1''s 20 km head start before car2 begins.'),
  ('CAT2018_QA_S2_18', 2018, 'Slot 2', 'CAT 2018 Slot 2 Official', TRUE, 'ALG_BASIC', 'If the sum of squares of two numbers is 97, which of the following cannot be their product?', 'mcq', '-32', '16', '48', '64', 'd', 'Since (a-b)²=97-2ab≥0, ab≤48.5, ruling out any product larger than that — so 64 is impossible.', NULL, 6, 'medium', 'medium', 120, 'Forgetting the (a-b)²≥0 constraint that upper-bounds the possible product.'),
  ('CAT2018_QA_S2_19', 2018, 'Slot 2', 'CAT 2018 Slot 2 Official', TRUE, 'GEO_MENS_2D', 'A rectangle''s area and the square of its perimeter are in ratio 1:25. Find the ratio of its shorter to longer side.', 'mcq', '1:4', '2:9', '1:3', '3:8', 'a', 'Setting ab/(2(a+b))²=1/25 leads to 4a²-17ab+4b²=0, factoring to (4a-b)(a-4b)=0; taking the valid root gives shorter:longer=1:4.', NULL, 6, 'medium', 'medium', 120, 'Accepting both algebraic roots without checking which one is consistent with ''shorter'' and ''longer'' sides.'),
  ('CAT2018_QA_S2_20', 2018, 'Slot 2', 'CAT 2018 Slot 2 Official', TRUE, 'GEO_CIRCLE_CHORD', 'Triangle ABC has a circle on diameter BC meeting AB, AC at P, Q. AB=30, AC=25, CP=20. Find BQ.', 'tita', NULL, NULL, NULL, NULL, '24', 'Since BC is a diameter, ∠BPC=∠BQC=90°, so BP⊥AB isn''t needed — instead using area of ABC two ways (via CP⊥AB and BQ⊥AC) gives BQ=(AB×CP)/AC=24.', NULL, 7, 'high', 'high', 150, 'Not recognising that P and Q give right angles (Thales'' theorem), which is key to relating the two altitudes.'),
  ('CAT2018_QA_S2_21', 2018, 'Slot 2', 'CAT 2018 Slot 2 Official', TRUE, 'GEO_LINE', 'Triangle ABC has area 32 sq units with BC (length 8) on the line x=4. Find the shortest possible distance from A to the origin.', 'mcq', '8 units', '4 units', '2√2 units', '4√2 units', 'b', 'The required altitude from A to BC is 2×32/8=8 units, so A lies on x=4-8=-4 (for minimum distance to origin); the closest such point is (-4,0), giving distance 4.', NULL, 6, 'medium', 'medium', 120, 'Not realising A must lie on x=-4 (closest to origin) to minimise distance, and instead using a general point on that vertical line.')
) AS v (
  external_id, year, slot, source, is_pyq,
  concept_code,
  question_text, question_type,
  option_a, option_b, option_c, option_d,
  correct_answer, solution, alternate_solution,
  difficulty, calculation_level, logic_level,
  expected_time_seconds, common_mistakes
)
JOIN subtopics s ON s.concept_code = v.concept_code
ON CONFLICT (exam_id, external_id) DO NOTHING;
